package com.farmrunautopilot;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

/**
 * Global settings. The run guidance highlights and colours (SPEC 13.4) are hidden here and edited in the sidebar's
 * Rules tab with everything else; the only visible item opens the sidebar.
 */
@ConfigGroup(FarmRunAutopilotConfig.GROUP)
public interface FarmRunAutopilotConfig extends Config
{
	String GROUP = "farmrunautopilot";
	String OPEN_SIDEBAR_KEY = "openSidebar";

	/** Works like a button: any click (tick or untick) opens the sidebar. */
	@ConfigItem(
		keyName = OPEN_SIDEBAR_KEY,
		name = "Click to open the sidebar",
		description = "All Farm Run Autopilot settings are in its sidebar panel. Each click here opens it.",
		position = 0
	)
	default boolean openSidebar()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightPatch",
		name = "Highlight the patch",
		description = "Outline the patch the current step is about",
		hidden = true,
		position = 1
	)
	default boolean highlightPatch()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hintArrow",
		name = "Hint arrow to the patch",
		description = "Point the game's hint arrow (also on the minimap) at the patch",
		hidden = true,
		position = 2
	)
	default boolean hintArrow()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightGardener",
		name = "Highlight the gardener",
		description = "Outline the gardener when the step is to pay them",
		hidden = true,
		position = 3
	)
	default boolean highlightGardener()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightItems",
		name = "Highlight items to use",
		description = "Outline the seed, compost, tool or teleport to use next in your inventory and equipment",
		hidden = true,
		position = 4
	)
	default boolean highlightItems()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "patchColour",
		name = "Patch colour",
		description = "Outline colour for the patch",
		hidden = true,
		position = 5
	)
	default Color patchColour()
	{
		return new Color(0, 255, 255, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "npcColour",
		name = "Gardener colour",
		description = "Outline colour for the gardener",
		hidden = true,
		position = 6
	)
	default Color npcColour()
	{
		return new Color(255, 215, 0, 220);
	}

	@Alpha
	@ConfigItem(
		keyName = "itemColour",
		name = "Item colour",
		description = "Outline colour for items to use",
		hidden = true,
		position = 7
	)
	default Color itemColour()
	{
		return new Color(0, 255, 0, 220);
	}
}

package com.farmrunautopilot;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.bank.FarmBankTab;
import com.farmrunautopilot.access.PohDetector;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.supply.SupplyLine;
import com.farmrunautopilot.supply.SupplyPlan;
import com.farmrunautopilot.route.RunOverrides;
import com.farmrunautopilot.route.RunPlan;
import com.farmrunautopilot.route.RunService;
import com.farmrunautopilot.run.GuidanceOverlay;
import com.farmrunautopilot.run.HighlightOverlay;
import com.farmrunautopilot.run.HintArrowController;
import com.farmrunautopilot.run.ItemHighlightOverlay;
import com.farmrunautopilot.run.RunSession;
import com.farmrunautopilot.run.RunView;
import com.farmrunautopilot.run.SceneTracker;
import com.farmrunautopilot.tracking.PatchTracker;
import com.farmrunautopilot.ui.FarmRunAutopilotPanel;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Farm Run Autopilot",
	description = "Plans and guides combined tree, fruit tree and herb farming runs",
	tags = {"farming", "farm", "run", "herb", "tree", "fruit", "route", "planner"}
)
public class FarmRunAutopilotPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private PatchTracker patchTracker;

	@Inject
	private SettingsStore settings;

	@Inject
	private AccessChecker accessChecker;

	@Inject
	private PohDetector pohDetector;

	@Inject
	private HoldingsTracker holdingsTracker;

	@Inject
	private RunService runService;

	@Inject
	private RunOverrides runOverrides;

	@Inject
	private ClientThread clientThread;

	@Inject
	private FarmBankTab farmBankTab;

	@Inject
	private RunSession runSession;

	@Inject
	private GuidanceOverlay guidanceOverlay;

	@Inject
	private HighlightOverlay highlightOverlay;

	@Inject
	private ItemHighlightOverlay itemHighlightOverlay;

	@Inject
	private SceneTracker sceneTracker;

	@Inject
	private HintArrowController hintArrow;

	@Inject
	private OverlayManager overlayManager;

	/** The session view last shown in the sidebar. */
	private RunView shownRunView;

	/** What the bank tab last showed: each line, amount needed and colour (not exact counts held). */
	private String bankTabContents = "";

	private final Runnable onSettingsReloaded = this::rebuildSetupLater;
	private final Runnable onSettingsSaved = () -> runService.markDirty();

	private FarmRunAutopilotPanel panel;
	private NavigationButton navButton;

	private WorldPoint lastTickLocation;
	private boolean lastTickPostLogin;
	private int lastModalCloseTick;

	@Override
	protected void startUp() throws Exception
	{
		settings.load();
		accessChecker.requestRefresh();
		panel = injector.getInstance(FarmRunAutopilotPanel.class);
		settings.addListener(onSettingsReloaded);
		settings.addSaveListener(onSettingsSaved);
		clientThread.invoke(holdingsTracker::loadCaches);
		farmBankTab.startUp(runService::getSupplies);
		overlayManager.add(guidanceOverlay);
		overlayManager.add(highlightOverlay);
		overlayManager.add(itemHighlightOverlay);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Farm Run Autopilot")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		log.debug("Farm Run Autopilot started");
	}

	@Override
	protected void shutDown() throws Exception
	{
		settings.removeListener(onSettingsReloaded);
		settings.removeSaveListener(onSettingsSaved);
		farmBankTab.shutDown();
		overlayManager.remove(guidanceOverlay);
		overlayManager.remove(highlightOverlay);
		overlayManager.remove(itemHighlightOverlay);
		itemHighlightOverlay.clearCache();
		clientThread.invoke(() ->
		{
			runSession.stop(false);
			hintArrow.clear();
			sceneTracker.clear();
		});
		shownRunView = null;
		clientToolbar.removeNavigation(navButton);
		panel.shutDown();
		navButton = null;
		panel = null;
		lastTickLocation = null;
		lastTickPostLogin = false;
		patchTracker.reset();
		accessChecker.reset();
		runService.reset();
		runOverrides.clear();
		log.debug("Farm Run Autopilot stopped");
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (accessChecker.onGameTick())
		{
			rebuildSetupLater();
			runService.markDirty();
		}
		if (runService.onGameTick())
		{
			final RunPlan plan = runService.getPlan();
			showPlanLater(plan, true);
			// Redraw the bank tab when a line or its colour changes. The bank redraws itself on every withdrawal,
			// but a tick before the plan catches up, so without this it would show the previous step.
			final String contents = bankTabContents(plan.getSupplies());
			if (!contents.equals(bankTabContents))
			{
				bankTabContents = contents;
				farmBankTab.refresh();
			}
		}

		runSession.onGameTick();
		hintArrow.update();
		final RunView runView = runSession.getView();
		if (!runView.equals(shownRunView))
		{
			shownRunView = runView;
			showPlanLater(runService.getPlan(), client.getGameState() == GameState.LOGGED_IN);
		}

		// Patch varbits are only sent after leaving the post-login welcome screen
		final Widget motw = client.getWidget(InterfaceID.WelcomeScreen.MOTW);
		if (motw != null && !motw.isHidden())
		{
			lastTickPostLogin = true;
			return;
		}
		if (lastTickPostLogin)
		{
			lastTickPostLogin = false;
			return;
		}

		final WorldPoint location = lastTickLocation;
		final Player player = client.getLocalPlayer();
		lastTickLocation = player == null ? null : player.getWorldLocation();

		// Skip ticks where the player crossed a region boundary
		if (location == null || lastTickLocation == null || location.getRegionID() != lastTickLocation.getRegionID())
		{
			return;
		}

		if (patchTracker.update(location, client.getTickCount() - lastModalCloseTick))
		{
			runService.markDirty();
			final FarmRunAutopilotPanel p = panel;
			SwingUtilities.invokeLater(p::refreshPatches);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getModalMode() != WidgetModalMode.NON_MODAL)
		{
			lastModalCloseTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		patchTracker.reset();
		accessChecker.reset();
		holdingsTracker.loadCaches();
		runService.reset();
		// Reloading notifies onSettingsReloaded, which rebuilds the Setup tab
		settings.load();
		final FarmRunAutopilotPanel p = panel;
		SwingUtilities.invokeLater(p::refreshPatches);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			accessChecker.requestRefresh();
			holdingsTracker.markDirty();
			runService.reset();
		}
		else if (event.getGameState() == GameState.LOADING)
		{
			// Objects are spawned again once the new scene loads; NPCs nearby aren't, so keep those
			sceneTracker.clearObjects();
		}
		else if (event.getGameState() == GameState.HOPPING)
		{
			sceneTracker.clear();
		}
		else if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			sceneTracker.clear();
			showPlanLater(RunPlan.EMPTY, false);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		accessChecker.onStatChanged(event.getSkill(), event.getLevel());
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		holdingsTracker.onItemContainerChanged(event.getContainerId(), event.getItemContainer());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		holdingsTracker.onVarbitChanged(event.getVarbitId());
		accessChecker.onVarbitChanged(event.getVarbitId());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
		{
			runSession.onChatMessage(Text.removeTags(event.getMessage()));
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		farmBankTab.onWidgetLoaded(event);
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		farmBankTab.onScriptCallbackEvent(event);
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		farmBankTab.onScriptPreFired(event);
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		farmBankTab.onScriptPostFired(event);
	}

	// After other plugins, so withdraw clicks are re-pointed last
	@Subscribe(priority = -1)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		farmBankTab.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		pohDetector.onObjectSpawned(event.getGameObject().getId());
		sceneTracker.onObjectSpawned(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		sceneTracker.onObjectDespawned(event.getGameObject());
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		sceneTracker.onNpcSpawned(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		sceneTracker.onNpcDespawned(event.getNpc());
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FarmRunAutopilotConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if ("itemColour".equals(event.getKey()))
		{
			itemHighlightOverlay.clearCache();
		}
		else if (FarmRunAutopilotConfig.OPEN_SIDEBAR_KEY.equals(event.getKey()))
		{
			// The config panel has no buttons and doesn't redraw a box we untick, so any click on it opens the sidebar
			SwingUtilities.invokeLater(() ->
			{
				if (navButton != null)
				{
					clientToolbar.openPanel(navButton);
				}
			});
		}
	}

	private static String bankTabContents(SupplyPlan plan)
	{
		final StringBuilder sb = new StringBuilder();
		for (SupplyLine line : plan.getLines())
		{
			sb.append(line.getName()).append('=').append(line.getNeed()).append(':').append(line.getStatus()).append(';');
		}
		return sb.toString();
	}

	private void showPlanLater(RunPlan plan, boolean loggedIn)
	{
		final FarmRunAutopilotPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.updateRun(plan, loggedIn));
		}
	}

	private void rebuildSetupLater()
	{
		final FarmRunAutopilotPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(p::rebuildSetup);
		}
	}

	@Provides
	FarmRunAutopilotConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FarmRunAutopilotConfig.class);
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.Requirement;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.travel.Spell;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelItem;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.AccountSettings;
import com.farmrunautopilot.settings.SettingsStore;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.gameval.VarbitID;

/**
 * Reads quests, diaries and skill levels on the client thread and publishes an {@link AccessSnapshot}
 * (SPEC 9). Results are cached and refreshed after login, on request, and every
 * {@link #REFRESH_TICKS} game ticks, never every tick.
 */
@Slf4j
@Singleton
public class AccessChecker
{
	/** Quests and diaries change rarely; re-read them about every 30 seconds. */
	private static final int REFRESH_TICKS = 50;

	private static final Set<Quest> QUESTS = EnumSet.of(Quest.FAIRYTALE_II__CURE_A_QUEEN, Quest.TREE_GNOME_VILLAGE);
	/** Every skill, since the max cape needs 99 in all of them. */
	private static final Set<Skill> SKILLS = AccessSnapshot.REAL_SKILLS;

	static
	{
		final List<Requirement> all = new ArrayList<>();
		for (Patch patch : Patch.values())
		{
			all.addAll(patch.getRequirements());
		}
		for (Spell spell : Spell.values())
		{
			all.addAll(spell.getRequirements());
		}
		for (TravelMethod method : TravelMethod.values())
		{
			all.addAll(method.getRequirements());
		}
		for (TravelItem item : TravelItem.values())
		{
			all.addAll(item.getRequirements());
		}
		for (Requirement requirement : all)
		{
			if (requirement.getQuest() != null)
			{
				QUESTS.add(requirement.getQuest());
			}
		}
	}

	private final Client client;
	private final SettingsStore settings;

	private volatile AccessSnapshot snapshot = AccessSnapshot.UNKNOWN;
	private volatile boolean refreshRequested = true;
	private int ticksSinceRefresh;

	@Inject
	AccessChecker(Client client, SettingsStore settings)
	{
		this.client = client;
		this.settings = settings;
	}

	public AccessSnapshot getSnapshot()
	{
		return snapshot;
	}

	/** Forget the previous account, e.g. after switching accounts. */
	public void reset()
	{
		snapshot = AccessSnapshot.UNKNOWN;
		refreshRequested = true;
	}

	/** Re-read on the next game tick if a level that matters changed. Ignores ordinary XP drops. */
	public void onStatChanged(Skill skill, int realLevel)
	{
		final AccessSnapshot current = snapshot;
		if (SKILLS.contains(skill) && current.isKnown() && current.level(skill) != realLevel)
		{
			refreshRequested = true;
		}
	}

	/** Re-read on the next game tick (after login or a Setup change). Any thread. */
	public void requestRefresh()
	{
		refreshRequested = true;
	}

	/**
	 * Call on the client thread every game tick.
	 *
	 * @return whether the snapshot changed
	 */
	public boolean onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		if (!refreshRequested && ++ticksSinceRefresh < REFRESH_TICKS)
		{
			return false;
		}
		refreshRequested = false;
		ticksSinceRefresh = 0;

		final AccessSnapshot next = read();
		if (next.equals(snapshot))
		{
			return false;
		}
		log.debug("Account access changed");
		snapshot = next;
		return true;
	}

	private AccessSnapshot read()
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		for (Quest quest : QUESTS)
		{
			quests.put(quest, quest.getState(client));
		}

		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		for (Skill skill : SKILLS)
		{
			levels.put(skill, client.getRealSkillLevel(skill));
		}

		final Set<String> diaries = new HashSet<>();
		for (AchievementDiary diary : AchievementDiary.values())
		{
			for (AchievementDiary.Tier tier : AchievementDiary.Tier.values())
			{
				if (client.getVarbitValue(diary.getCompleteVarbit(tier)) > 0)
				{
					diaries.add(AccessSnapshot.diaryKey(diary, tier));
				}
			}
		}

		final AccountSettings account = settings.getAccount();
		final Set<Unlock> unlocks = EnumSet.noneOf(Unlock.class);
		unlocks.addAll(account.getManualUnlocks());
		// A dramen or lunar staff is also needed unless the Elite Lumbridge diary is done; the supply
		// calculator (M4) checks for the staff.
		if (quests.get(Quest.FAIRYTALE_II__CURE_A_QUEEN) != QuestState.NOT_STARTED)
		{
			unlocks.add(Unlock.FAIRY_RINGS);
		}
		if (quests.get(Quest.TREE_GNOME_VILLAGE) == QuestState.FINISHED)
		{
			unlocks.add(Unlock.SPIRIT_TREES);
		}

		final PohAltar altar = account.getPoh().getAltar();
		return new AccessSnapshot(true, Collections.unmodifiableMap(quests), Collections.unmodifiableMap(levels),
			Collections.unmodifiableSet(diaries), Collections.unmodifiableSet(unlocks), account.getPoh().getPortal(),
			spellbook(client.getVarbitValue(VarbitID.SPELLBOOK)),
			altar != null ? altar.getSpellbooks() : Collections.emptySet());
	}

	/** The SPELLBOOK varbit: 0 standard, 1 ancient, 2 lunar, 3 arceuus; null for anything else. */
	static Spellbook spellbook(int value)
	{
		switch (value)
		{
			case 0:
				return Spellbook.STANDARD;
			case 1:
				return Spellbook.ANCIENT;
			case 2:
				return Spellbook.LUNAR;
			case 3:
				return Spellbook.ARCEUUS;
			default:
				return null;
		}
	}

	/** Re-read soon if the varbit is the spellbook. Client thread. */
	public void onVarbitChanged(int varbitId)
	{
		if (varbitId == VarbitID.SPELLBOOK)
		{
			refreshRequested = true;
		}
	}

	/** Unlocks that are worked out automatically, so Setup shows them as detected rather than a toggle. */
	public static boolean isDetected(Unlock unlock)
	{
		return unlock == Unlock.FAIRY_RINGS || unlock == Unlock.SPIRIT_TREES;
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.AchievementDiary;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.Requirement;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.HousePortal;
import com.farmrunautopilot.data.travel.Spell;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelMethod;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Value;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;

/**
 * An immutable picture of what the account has unlocked (SPEC 9), safe to read from any thread.
 */
@Value
public class AccessSnapshot
{
	/** Before the first login: nothing is known, so nothing shows as locked. */
	public static final AccessSnapshot UNKNOWN = new AccessSnapshot(false, Collections.emptyMap(),
		Collections.emptyMap(), Collections.emptySet(), Collections.emptySet(), null);

	/**
	 * Every skill. In this RuneLite version {@code Skill.OVERALL} is a deprecated field left as null, not an
	 * enum value, so {@code Skill.values()} already has only real skills.
	 */
	public static final Set<Skill> REAL_SKILLS = Collections.unmodifiableSet(EnumSet.allOf(Skill.class));

	/** False until real account data has been read. */
	boolean known;
	Map<Quest, QuestState> quests;
	Map<Skill, Integer> realLevels;
	/** Completed diaries as "DIARY:TIER", e.g. "FALADOR:ELITE". */
	Set<String> completedDiaries;
	/** Detected unlocks plus the ones the player ticked by hand. */
	Set<Unlock> unlocks;
	/** House portal location from My POH, or null. */
	HousePortal housePortal;
	/** The spellbook the player is on, or null if unknown. */
	Spellbook spellbook;
	/** Spellbooks a POH altar can switch to (empty without one). */
	Set<Spellbook> altarSpellbooks;

	public AccessSnapshot(boolean known, Map<Quest, QuestState> quests, Map<Skill, Integer> realLevels,
		Set<String> completedDiaries, Set<Unlock> unlocks, HousePortal housePortal, Spellbook spellbook,
		Set<Spellbook> altarSpellbooks)
	{
		this.known = known;
		this.quests = quests;
		this.realLevels = realLevels;
		this.completedDiaries = completedDiaries;
		this.unlocks = unlocks;
		this.housePortal = housePortal;
		this.spellbook = spellbook;
		this.altarSpellbooks = altarSpellbooks;
	}

	/** Without spellbook information: any book counts as usable. */
	public AccessSnapshot(boolean known, Map<Quest, QuestState> quests, Map<Skill, Integer> realLevels,
		Set<String> completedDiaries, Set<Unlock> unlocks, HousePortal housePortal)
	{
		this(known, quests, realLevels, completedDiaries, unlocks, housePortal, null, Collections.emptySet());
	}

	public static String diaryKey(AchievementDiary diary, AchievementDiary.Tier tier)
	{
		return diary.name() + ":" + tier.name();
	}

	public boolean isMet(Requirement requirement)
	{
		if (!known)
		{
			return true;
		}
		switch (requirement.getKind())
		{
			case QUEST_COMPLETE:
				return quests.get(requirement.getQuest()) == QuestState.FINISHED;
			case QUEST_STARTED:
			{
				final QuestState state = quests.get(requirement.getQuest());
				return state != null && state != QuestState.NOT_STARTED;
			}
			case SKILL:
				return level(requirement.getSkill()) >= requirement.getLevel();
			case DIARY:
				return completedDiaries.contains(diaryKey(requirement.getDiary(), requirement.getDiaryTier()));
			case UNLOCK:
				return unlocks.contains(requirement.getUnlock());
			case HOUSE_PORTAL:
				return requirement.getHousePortal() == housePortal;
			case ALL_SKILLS:
				for (Skill skill : REAL_SKILLS)
				{
					if (level(skill) < requirement.getLevel())
					{
						return false;
					}
				}
				return true;
			case ALL_DIARIES:
				for (AchievementDiary diary : AchievementDiary.values())
				{
					if (!completedDiaries.contains(diaryKey(diary, requirement.getDiaryTier())))
					{
						return false;
					}
				}
				return true;
			default:
				return false;
		}
	}

	public int level(Skill skill)
	{
		final Integer level = realLevels.get(skill);
		return level != null ? level : 1;
	}

	/**
	 * @return the requirements that aren't met, empty if everything is
	 */
	public List<Requirement> missing(List<Requirement> requirements)
	{
		final List<Requirement> missing = new ArrayList<>();
		for (Requirement requirement : requirements)
		{
			if (!isMet(requirement))
			{
				missing.add(requirement);
			}
		}
		return missing;
	}

	public List<Requirement> missingFor(Patch patch)
	{
		return missing(patch.getRequirements());
	}

	/**
	 * Requirements for a travel method: its own, the item's, the spell's quest, and the spell's Magic level
	 * when there is no tablet (tablets work at any Magic level). Owning the item, tablet or runes is checked
	 * by the supply calculator (M4), not here.
	 */
	public List<Requirement> missingFor(TravelMethod method)
	{
		final List<Requirement> all = new ArrayList<>(method.getRequirements());
		if (method.getItem() != null)
		{
			all.addAll(method.getItem().getRequirements());
		}
		final Spell spell = method.getSpell();
		if (spell != null)
		{
			all.addAll(spell.getRequirements());
			if (!spell.hasTablet())
			{
				all.add(Requirement.skill(Skill.MAGIC, spell.getMagicLevel()));
			}
		}
		return missing(all);
	}

	/**
	 * Whether the player can cast this spell rather than needing its tablet: Magic level, quest, and being on
	 * its spellbook (or able to switch with a house altar). Sean asked not to hop spellbooks otherwise.
	 */
	public boolean canCast(Spell spell)
	{
		return !known || (level(Skill.MAGIC) >= spell.getMagicLevel() && missing(spell.getRequirements()).isEmpty()
			&& (isOnSpellbook(spell) || altarSpellbooks.contains(spell.getSpellbook())));
	}

	/** On the spell's spellbook right now (or the spellbook isn't known). */
	public boolean isOnSpellbook(Spell spell)
	{
		return spellbook == null || spellbook == spell.getSpellbook();
	}

	/** Tooltip text listing what's missing, e.g. "Needs 65 Farming, Needs Priest in Peril". */
	public static String describe(List<Requirement> missing)
	{
		final List<String> parts = new ArrayList<>();
		for (Requirement requirement : missing)
		{
			parts.add(requirement.describe());
		}
		return String.join(", ", parts);
	}
}

package com.farmrunautopilot.access;

import com.farmrunautopilot.data.poh.JewelleryBoxTier;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.poh.PoolTier;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.SettingsStore;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.gameval.ObjectID;

/**
 * Fills in My POH from house furniture as it loads (SPEC 2 "auto-detect on visit"). Driven by object
 * spawn events, never by scanning the scene.
 *
 * <p>Detection only ever adds or upgrades, because objects in another player's house look the same
 * and a partly loaded house would otherwise wipe settings. The house portal location and nexus
 * destinations can't be read this way and stay manual.
 */
@Slf4j
@Singleton
public class PohDetector
{
	private final SettingsStore settings;
	private final AccessChecker accessChecker;

	@Inject
	PohDetector(SettingsStore settings, AccessChecker accessChecker)
	{
		this.settings = settings;
		this.accessChecker = accessChecker;
	}

	/** Call for every spawned game object. Cheap for objects that aren't POH furniture. */
	public void onObjectSpawned(int objectId)
	{
		final JewelleryBoxTier box = jewelleryBoxFor(objectId);
		final PoolTier pool = poolFor(objectId);
		final boolean fairyRing = objectId == ObjectID.POH_FAIRY_RING || objectId == ObjectID.POH_SPIRIT_RING;
		final boolean spiritTree = objectId == ObjectID.POH_SPIRIT_TREE || objectId == ObjectID.POH_SPIRIT_RING;
		final PohAltar altar = altarFor(objectId);
		if (box == null && pool == null && altar == null && !fairyRing && !spiritTree)
		{
			return;
		}

		// Settings are only changed on the Swing thread.
		SwingUtilities.invokeLater(() -> apply(box, pool, altar, fairyRing, spiritTree));
	}

	private void apply(JewelleryBoxTier box, PoolTier pool, PohAltar altar, boolean fairyRing, boolean spiritTree)
	{
		final PohSetup poh = settings.getAccount().getPoh();
		boolean changed = false;
		if (box != null && (poh.getJewelleryBox() == null || box.ordinal() > poh.getJewelleryBox().ordinal()))
		{
			poh.setJewelleryBox(box);
			changed = true;
		}
		if (pool != null && (poh.getPool() == null || pool.ordinal() > poh.getPool().ordinal()))
		{
			poh.setPool(pool);
			changed = true;
		}
		// The occult altar covers every spellbook, so it beats the others
		if (altar != null && poh.getAltar() != altar && poh.getAltar() != PohAltar.OCCULT)
		{
			poh.setAltar(altar);
			changed = true;
		}
		if (fairyRing && !poh.isFairyRing())
		{
			poh.setFairyRing(true);
			changed = true;
		}
		if (spiritTree && !poh.isSpiritTree())
		{
			poh.setSpiritTree(true);
			changed = true;
		}

		poh.setLastDetected(Instant.now().getEpochSecond());
		if (changed)
		{
			log.debug("Detected POH furniture: box={} pool={} altar={} fairyRing={} spiritTree={}", box, pool, altar, fairyRing,
				spiritTree);
		}
		// Always save so "last detected" updates; refresh the tab only when something new was found.
		settings.saveAccount(changed);
		if (changed)
		{
			accessChecker.requestRefresh();
		}
	}

	static JewelleryBoxTier jewelleryBoxFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_JEWELLERY_BOX_1:
				return JewelleryBoxTier.BASIC;
			case ObjectID.POH_JEWELLERY_BOX_2:
				return JewelleryBoxTier.FANCY;
			case ObjectID.POH_JEWELLERY_BOX_3:
				return JewelleryBoxTier.ORNATE;
			default:
				return null;
		}
	}

	static PohAltar altarFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_ALTAR_ANCIENT:
				return PohAltar.ANCIENT;
			case ObjectID.POH_ALTAR_LUNAR:
				return PohAltar.LUNAR;
			case ObjectID.POH_ALTAR_DARK:
				return PohAltar.DARK;
			case ObjectID.POH_ALTAR_OCCULT:
			case ObjectID.POH_ALTAR_OCCULT_STANDARD:
			case ObjectID.POH_ALTAR_OCCULT_ANCIENT:
			case ObjectID.POH_ALTAR_OCCULT_LUNAR:
			case ObjectID.POH_ALTAR_OCCULT_ARCEUUS:
				return PohAltar.OCCULT;
			default:
				return null;
		}
	}

	static PoolTier poolFor(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.POH_POOL_RESTORATION:
				return PoolTier.RESTORATION;
			case ObjectID.POH_POOL_REVITALISATION:
				return PoolTier.REVITALISATION;
			case ObjectID.POH_POOL_REJUVENATION:
				return PoolTier.REJUVENATION;
			// UNVERIFIED: "recovery" and "regeneration" are assumed to be the fancy and ornate pools.
			case ObjectID.POH_POOL_RECOVERY:
				return PoolTier.FANCY_REJUVENATION;
			case ObjectID.POH_POOL_REGENERATION:
				return PoolTier.ORNATE_REJUVENATION;
			default:
				return null;
		}
	}
}

