package com.farmrunautopilot.route;

import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.tracking.PatchPrediction;
import com.farmrunautopilot.tracking.PatchStatusText;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

/**
 * Decides which patches the next run covers (SPEC 10).
 *
 * <ul>
 * <li>A patch is due unless it is still growing; never-seen patches count as due.</li>
 * <li>A ticked run type is included when at least the threshold percentage of its usable patches are due
 * (100% by default), unless the player overrides it for this run.</li>
 * <li>Within an included type, patches that aren't due are left out with a reason.</li>
 * </ul>
 */
public final class RunSelector
{
	private RunSelector()
	{
	}

	/**
	 * @param fullRun include every selected patch, ignoring due rules (testing)
	 */
	public static RunSelection select(RunConfig config, AccessSnapshot access,
		Function<Patch, PatchPrediction> predictions, long now, boolean fullRun, Map<PatchType, TypeOverride> overrides)
	{
		final List<Patch> patches = new ArrayList<>();
		final Set<PatchType> included = EnumSet.noneOf(PatchType.class);
		final Map<PatchType, Long> skipped = new EnumMap<>(PatchType.class);
		final List<String> notDue = new ArrayList<>();
		final Map<PatchType, Integer> dueCounts = new EnumMap<>(PatchType.class);

		for (PatchType type : PatchType.values())
		{
			if (!config.getEnabledTypes().contains(type))
			{
				continue;
			}
			final List<Patch> usable = new ArrayList<>();
			for (Patch patch : Patch.values())
			{
				if (patch.getType() == type && config.isPatchSelected(patch) && access.missingFor(patch).isEmpty())
				{
					usable.add(patch);
				}
			}
			if (usable.isEmpty())
			{
				continue;
			}

			int due = 0;
			final List<Long> readyTimes = new ArrayList<>();
			for (Patch patch : usable)
			{
				final PatchPrediction prediction = predictions.apply(patch);
				if (isDue(prediction))
				{
					due++;
					readyTimes.add(now);
				}
				else
				{
					readyTimes.add(prediction.getDoneAt());
				}
			}
			dueCounts.put(type, due);

			final int needed = neededDue(usable.size(), config.getDueThresholdPercent());
			final TypeOverride override = overrides.get(type);
			final boolean include = fullRun
				|| override == TypeOverride.INCLUDE
				|| (override != TypeOverride.SKIP && due >= needed && due > 0);
			if (!include)
			{
				Collections.sort(readyTimes);
				final long readyAt = override == TypeOverride.SKIP ? 0 : readyTimes.get(Math.max(needed, 1) - 1);
				skipped.put(type, readyAt);
				continue;
			}

			included.add(type);
			for (Patch patch : usable)
			{
				final PatchPrediction prediction = predictions.apply(patch);
				if (fullRun || isDue(prediction))
				{
					patches.add(patch);
				}
				else
				{
					notDue.add(patch.getDisplayName() + ": " + PatchStatusText.describe(prediction, now));
				}
			}
		}
		return new RunSelection(patches, included, skipped, notDue, dueCounts);
	}

	/** A patch is due unless it is still growing (SPEC 10). Never-seen patches count as due. */
	public static boolean isDue(PatchPrediction prediction)
	{
		return prediction == null || prediction.getState() != PatchState.GROWING;
	}

	/** How many of {@code total} patches must be due to reach {@code percent}, rounded up. */
	static int neededDue(int total, int percent)
	{
		return (total * percent + 99) / 100;
	}
}

package com.farmrunautopilot.route;

import com.farmrunautopilot.access.AccessChecker;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.run.RunTimings;
import com.farmrunautopilot.run.StepAdvisor;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import com.farmrunautopilot.supply.Holdings;
import com.farmrunautopilot.supply.HoldingsTracker;
import com.farmrunautopilot.supply.SupplyCalculator;
import com.farmrunautopilot.supply.SupplyPlan;
import com.farmrunautopilot.tracking.PatchTracker;
import java.time.Instant;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemManager;

/**
 * Works out the next run on the client thread, at most once per game tick, when something it depends on
 * changes: which patches (SPEC 10), the route (SPEC 12) and the supplies (SPEC 11).
 */
@Singleton
public class RunService
{
	/** Patches become due as they grow, so recalculate about once a minute regardless. */
	private static final int REFRESH_TICKS = 100;

	private final Client client;
	private final ItemManager itemManager;
	private final SettingsStore settings;
	private final AccessChecker accessChecker;
	private final PatchTracker patchTracker;
	private final HoldingsTracker holdingsTracker;
	private final RunOverrides overrides;
	private final RunTimings timings;
	/** Item names are fixed, so look each up once. */
	private final Map<Integer, String> names = new HashMap<>();

	private volatile boolean dirty = true;
	/** Null until the first plan after login, so that one is always published. */
	private volatile RunPlan plan;
	private int ticksSinceRefresh;

	@Inject
	RunService(Client client, ItemManager itemManager, SettingsStore settings, AccessChecker accessChecker,
		PatchTracker patchTracker, HoldingsTracker holdingsTracker, RunOverrides overrides, RunTimings timings)
	{
		this.timings = timings;
		this.client = client;
		this.itemManager = itemManager;
		this.settings = settings;
		this.accessChecker = accessChecker;
		this.patchTracker = patchTracker;
		this.holdingsTracker = holdingsTracker;
		this.overrides = overrides;
	}

	public RunPlan getPlan()
	{
		final RunPlan current = plan;
		return current != null ? current : RunPlan.EMPTY;
	}

	public SupplyPlan getSupplies()
	{
		return getPlan().getSupplies();
	}

	/** Forget the last plan (login, account switch) so the next one is always published. Any thread. */
	public void reset()
	{
		plan = null;
		dirty = true;
	}

	/** Recalculate on the next game tick. Any thread. */
	public void markDirty()
	{
		dirty = true;
	}

	/**
	 * @return whether a new plan was made
	 */
	public boolean onGameTick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		final boolean holdingsChanged = holdingsTracker.rebuildIfDirty();
		if (!holdingsChanged && !dirty && ++ticksSinceRefresh < REFRESH_TICKS)
		{
			return false;
		}
		dirty = false;
		ticksSinceRefresh = 0;

		final RunConfig config = settings.getRunConfig();
		final AccessSnapshot access = accessChecker.getSnapshot();
		final Holdings holdings = holdingsTracker.getHoldings();
		final RunSelection selection = RunSelector.select(config, access, patchTracker::predict,
			Instant.now().getEpochSecond(), config.isSupplyFullRun(), overrides.get());
		final Route route = RoutePlanner.plan(selection.getPatches(), config, access, holdings,
			settings.getAccount().getPoh(), timings.learned());
		final SupplyPlan supplies = SupplyCalculator.calculate(config, access, holdings, selection, route,
			patchTracker::predict, this::itemName, itemManager::getItemPrice);

		final Map<Location, List<String>> objectives = new EnumMap<>(Location.class);
		for (Patch patch : selection.getPatches())
		{
			objectives.computeIfAbsent(patch.getLocation(), k -> new ArrayList<>()).add(StepAdvisor.objectives(
				patch, patchTracker.predict(patch), supplies.getPlantings().get(patch)));
		}

		final RunPlan next = new RunPlan(selection, route, supplies, objectives);
		if (next.equals(plan))
		{
			return false;
		}
		plan = next;
		return true;
	}

	/** The noted version of an item (or the item itself if it has none). Client thread. */
	public int notedId(int itemId)
	{
		final int noted = itemManager.getItemComposition(itemId).getLinkedNoteId();
		return noted > 0 ? noted : itemId;
	}

	/** An item's name, looked up once. Client thread. */
	public String itemName(int itemId)
	{
		return names.computeIfAbsent(itemId, id -> itemManager.getItemComposition(id).getName());
	}
}

