/**
 * Runs a farm run from Start to Stop (SPEC 13.4): freezes the plan, works out the next step from live patch
 * states, notices when steps are done, records leg times, and finishes itself after the last step.
 *
 * <p>All methods except {@link #getView()} run on the client thread.
 */
@Slf4j
@Singleton
public class RunSession
{
	/** Compost messages, as in RuneLite core CompostTracker (BSD-2). */
	private static final Pattern COMPOST_USED = Pattern.compile(
		"You treat the .+ with (ultra|super|)compost\\.|^The .+ has been treated with (ultra|super|)compost.*");
	private static final Pattern ALREADY_COMPOSTED = Pattern.compile(
		"This .+ has already been (treated|fertilised) with (ultra|super|)compost.*");
	/** How long "Run finished" stays under the player. */
	private static final long FINISHED_NOTICE_MILLIS = 15_000;
	/** Further than this from a patch and the step starts with "Run to the ... patch". */
	private static final int NEAR_PATCH_TILES = 7;
	private static final int BEST_TIMES = 3;
	private static final int INVENTORY_SLOTS = 28;

	private final Client client;
	private final RunService runService;
	private final PatchTracker patchTracker;
	private final HoldingsTracker holdingsTracker;
	private final AccessChecker accessChecker;
	private final SettingsStore settings;
	private final RunTimings timings;
	private final SceneTracker scene;

	private boolean running;
	private RunPlan plan;
	private long startedAt;
	private int stopIndex;
	private boolean arrived;
	/** When the player reached the current stop (epoch seconds); patches must be seen after this to count. */
	private long arrivedAtSeconds;
	/** The time for the leg to the current stop has been saved. */
	private boolean legRecorded;
	private long legStartedAt;
	private Patch currentPatch;
	/** What to do at {@link #currentPatch}, or null while travelling. */
	private StepAdvisor.Action currentAction;
	private final Map<Patch, Progress> progress = new EnumMap<>(Patch.class);
	private final List<RunTimings.Leg> legs = new ArrayList<>();
	private long finishedAt;
	private String lastRun;
	private volatile RunView view = RunView.IDLE_VIEW;

	/** What has happened at a patch during this run. */
	private static final class Progress
	{
		boolean composted;
		boolean paid;
		boolean skipped;
		/** Seen in range in a state other than growing, so a crop growing later was planted this run. */
		boolean sawUnplanted;
		/** Payment items in the inventory when paying became the next step; -1 until then. */
		int paymentBaseline = -1;
	}

	@Inject
	RunSession(Client client, RunService runService, PatchTracker patchTracker, HoldingsTracker holdingsTracker,
		AccessChecker accessChecker, SettingsStore settings, RunTimings timings,
		SceneTracker scene)
	{
		this.scene = scene;
		this.client = client;
		this.runService = runService;
		this.patchTracker = patchTracker;
		this.holdingsTracker = holdingsTracker;
		this.accessChecker = accessChecker;
		this.settings = settings;
		this.timings = timings;
	}

	public RunView getView()
	{
		return view;
	}

	/** Freeze the current plan and start guiding. */
	public void start()
	{
		final RunPlan current = runService.getPlan();
		if (running || current.getRoute().getStops().isEmpty())
		{
			return;
		}
		plan = current;
		running = true;
		startedAt = System.currentTimeMillis();
		legStartedAt = startedAt;
		stopIndex = 0;
		arrived = false;
		currentPatch = null;
		progress.clear();
		legs.clear();
		lastRun = null;
		log.debug("Run started with {} stops", plan.getRoute().getStops().size());
		onGameTick();
	}

	/**
	 * End the run and save its timings.
	 *
	 * @param finished every stop was completed
	 */
	public void stop(boolean finished)
	{
		if (!running)
		{
			return;
		}
		running = false;
		final long now = System.currentTimeMillis();
		final double seconds = (now - startedAt) / 1000.0;
		final Map<PatchType, Integer> counts = plan.getSupplies().getPatchCounts();
		final String makeup = RunTimings.makeup(counts);
		timings.save(new ArrayList<>(legs), new RunTimings.Run(startedAt, seconds, stopIndex, finished, makeup));
		finishedAt = now;
		lastRun = (finished ? "Run finished in " : "Run stopped after ") + GuidanceOverlay.clock((long) seconds);
		if (finished)
		{
			lastRun += rank(timings.best(makeup, BEST_TIMES), seconds, RunTimings.makeupName(counts));
		}
		log.debug("Run ended: {}", lastRun);
		plan = null;
		// Replan with the newly learned leg times
		runService.markDirty();
		onGameTick();
	}

	/** e.g. " - new best for 6 herbs!" or " - 2nd best for 6 herbs"; empty outside the top times. */
	static String rank(List<Double> best, double seconds, String makeupName)
	{
		final int place = best.indexOf(seconds);
		if (place < 0)
		{
			return "";
		}
		if (best.size() == 1)
		{
			return " - first time for " + makeupName;
		}
		if (place == 0)
		{
			return " - new best for " + makeupName + "!";
		}
		return " - " + (place == 1 ? "2nd" : "3rd") + " best for " + makeupName;
	}

	/** e.g. "Best for 6 herbs: 8:12, 8:40, 9:03", or null with none yet. */
	private String bestTimes(RunPlan current)
	{
		final Map<PatchType, Integer> counts = current.getSupplies().getPatchCounts();
		final String makeup = RunTimings.makeup(counts);
		if (makeup.isEmpty())
		{
			return null;
		}
		final List<Double> best = timings.best(makeup, BEST_TIMES);
		if (best.isEmpty())
		{
			return null;
		}
		final List<String> clocks = new ArrayList<>();
		for (double seconds : best)
		{
			clocks.add(GuidanceOverlay.clock((long) seconds));
		}
		return "Best for " + RunTimings.makeupName(counts) + ": " + String.join(", ", clocks);
	}

	/** Skip whatever the next step is (arriving, or the current patch). */
	public void skip()
	{
		if (!running)
		{
			return;
		}
		if (!arrived)
		{
			markArrived(System.currentTimeMillis());
		}
		else if (currentPatch != null)
		{
			progress(currentPatch).skipped = true;
		}
		onGameTick();
	}

	public void onChatMessage(String message)
	{
		if (running && currentPatch != null
			&& (COMPOST_USED.matcher(message).matches() || ALREADY_COMPOSTED.matcher(message).matches()))
		{
			progress(currentPatch).composted = true;
		}
	}

	/** Re-evaluate the run. Call every game tick. */
	public void onGameTick()
	{
		if (!running)
		{
			view = idleView();
			return;
		}

		final List<RouteStop> stops = plan.getRoute().getStops();
		final long now = System.currentTimeMillis();
		String instruction = null;
		while (stopIndex < stops.size())
		{
			final RouteStop stop = stops.get(stopIndex);
			final List<Patch> here = patchesAt(stop.getLocation());
			if (!arrived)
			{
				if (inRange(here))
				{
					markArrived(now);
				}
				else
				{
					instruction = stop.describeTravel() + " to " + stop.getLocation().getDisplayName();
					currentPatch = null;
					break;
				}
			}
			if (!legRecorded && nearAny(here))
			{
				recordLeg(now);
			}

			instruction = nextPatchStep(here);
			if (instruction != null)
			{
				break;
			}
			// Every patch here is done
			if (!legRecorded)
			{
				recordLeg(now);
			}
			stopIndex++;
			arrived = false;
			legStartedAt = now;
		}

		if (stopIndex >= stops.size())
		{
			stop(true);
			return;
		}
		view = runningView(instruction);
	}


	/** The first unfinished step at this stop, or null when every patch here is done. */
	private String nextPatchStep(List<Patch> here)
	{
		for (Patch patch : here)
		{
			final Progress p = progress(patch);
			if (p.skipped)
			{
				continue;
			}
			final PatchPrediction live = patchTracker.predict(patch);
			// Only trust a reading taken since arriving: an estimate from the last visit can say a tree is
			// still growing when it's ready, which would skip the patch
			if (live == null || live.getObservedAt() < arrivedAtSeconds)
			{
				currentPatch = patch;
				currentAction = StepAdvisor.Action.INSPECT;
				return "Walk to the " + patch.getDisplayName() + " patch";
			}
			if (live.getState() != PatchState.GROWING && patchTracker.getPatchesInRange().contains(patch))
			{
				p.sawUnplanted = true;
			}
			final StepAdvisor.PatchGoal goal = goal(patch, p);
			final StepAdvisor.Advice advice = StepAdvisor.advise(goal, live);
			if (advice.getAction() == StepAdvisor.Action.PAY)
			{
				watchPayment(patch, p);
				if (p.paid)
				{
					continue;
				}
			}
			if (advice.getAction() != StepAdvisor.Action.DONE)
			{
				currentPatch = patch;
				currentAction = advice.getAction();
				// The area loads well before the patch is reached, and some places have several patches
				if (advice.getAction() != StepAdvisor.Action.INSPECT && farFrom(patch))
				{
					final String text = advice.getText();
					final TravelMethod method = plan.getRoute().getStops().get(stopIndex).getMethod();
					final String directions = method != null ? method.getDirections() : null;
					return (directions != null ? directions + " to the " : "Run to the ") + patch.getDisplayName()
						+ " patch, then "
						+ Character.toLowerCase(text.charAt(0)) + text.substring(1);
				}
				return advice.getText();
			}
		}
		currentPatch = null;
		return null;
	}

	/** Paid once the payment items leave the inventory after paying became the next step. */
	private void watchPayment(Patch patch, Progress p)
	{
		final Crop crop = plan.getSupplies().getPlantings().get(patch);
		if (crop == null || !crop.hasPayment())
		{
			return;
		}
		final int held = holdingsTracker.getHoldings().in(Holdings.Source.INVENTORY)
			.getOrDefault(crop.getPaymentItemId(), 0);
		if (p.paymentBaseline < 0)
		{
			p.paymentBaseline = held;
		}
		else if (held < p.paymentBaseline)
		{
			p.paid = true;
		}
	}

	private StepAdvisor.PatchGoal goal(Patch patch, Progress p)
	{
		final RunConfig config = settings.getRunConfig();
		final AccessSnapshot access = accessChecker.getSnapshot();
		final Crop crop = plan.getSupplies().getPlantings().get(patch);
		final boolean faladorElite = patch == Patch.FALADOR_TREE && access.isKnown()
			&& access.isMet(Requirement.diary(AchievementDiary.FALADOR, AchievementDiary.Tier.ELITE));
		final boolean protectionNeeded = patch.getType().isProtectable() && crop != null && crop.hasPayment()
			&& config.protectionFor(patch) == Protection.PAY_GARDENER && !faladorElite;
		final String plantName = crop != null ? runService.itemName(crop.getPlantItemId()) : "your seed";
		final String payment = protectionNeeded
			? crop.getPaymentQuantity() + " x " + runService.itemName(crop.getPaymentItemId())
			+ (config.isPayWithNotes() ? " (noted is fine)" : "")
			: null;
		return new StepAdvisor.PatchGoal(patch, crop, plantName, config.getCompost().get(patch.getType()),
			protectionNeeded, payment, config.getPayToClear().contains(patch.getType()), p.composted, p.paid, p.sawUnplanted);
	}

	private void markArrived(long now)
	{
		arrived = true;
		arrivedAtSeconds = now / 1000;
		legRecorded = false;
	}

	/**
	 * Save the time for the leg to the current stop. Recorded on reaching a patch rather than when its area
	 * loads, to match the estimates, which include the walk from the teleport spot.
	 */
	private void recordLeg(long now)
	{
		legRecorded = true;
		final RouteStop stop = plan.getRoute().getStops().get(stopIndex);
		// The trip to the first stop starts from wherever the player banked, so it isn't a sample for
		// learning our methods' times.
		final boolean first = stopIndex == 0;
		legs.add(new RunTimings.Leg(stop.getLocation().name(),
			first || stop.getMethod() == null ? null : stop.getMethod().name(),
			first ? "START" : stop.getDeparture().name(), (now - legStartedAt) / 1000.0, now));
	}

	private List<Patch> patchesAt(Location location)
	{
		final List<Patch> here = new ArrayList<>();
		for (Patch patch : plan.getSelection().getPatches())
		{
			if (patch.getLocation() == location)
			{
				here.add(patch);
			}
		}
		return here;
	}

	private boolean inRange(List<Patch> here)
	{
		final Set<Patch> inRange = patchTracker.getPatchesInRange();
		for (Patch patch : here)
		{
			if (inRange.contains(patch))
			{
				return true;
			}
		}
		return false;
	}

	private boolean nearAny(List<Patch> here)
	{
		for (Patch patch : here)
		{
			if (!farFrom(patch))
			{
				return true;
			}
		}
		return false;
	}

	private boolean farFrom(Patch patch)
	{
		final Player player = client.getLocalPlayer();
		final WorldPoint point = scene.locationOf(patch);
		return player != null && point != null && player.getWorldLocation().distanceTo(point) > NEAR_PATCH_TILES;
	}

	private Progress progress(Patch patch)
	{
		return progress.computeIfAbsent(patch, k -> new Progress());
	}

	private RunView runningView(String instruction)
	{
		final List<RunView.Stop> stopViews = new ArrayList<>();
		final List<RouteStop> stops = plan.getRoute().getStops();
		for (int i = 0; i < stops.size(); i++)
		{
			final RouteStop stop = stops.get(i);
			final RunView.StopStatus status = i < stopIndex ? RunView.StopStatus.DONE
				: i == stopIndex ? RunView.StopStatus.CURRENT : RunView.StopStatus.PENDING;
			final String travel = stop.describeTravel();
			stopViews.add(new RunView.Stop(stop.getLocation().getDisplayName(), travel, status,
				status == RunView.StopStatus.CURRENT ? instruction : null,
				plan.getObjectives().getOrDefault(stop.getLocation(), Collections.emptyList())));
		}
		final Highlights highlights = highlights();
		return new RunView(RunView.State.RUNNING, startedAt, stopViews, instruction, false, null, null,
			reminders(highlights), highlights);
	}

	/** What the current step points at: the patch and items to use there, or the teleport item while travelling. */
	private Highlights highlights()
	{
		// Main item first: reminders name it
		final Set<Integer> items = new LinkedHashSet<>();
		if (currentPatch == null || currentAction == null)
		{
			final RouteStop stop = plan.getRoute().getStops().get(stopIndex);
			if (stopIndex > 0 && stop.getDeparture() == Departure.DIRECT && stop.getMethod() != null)
			{
				travelItems(stop.getMethod(), items);
			}
			return new Highlights(null, false, items);
		}

		boolean gardener = false;
		final Crop crop = plan.getSupplies().getPlantings().get(currentPatch);
		switch (currentAction)
		{
			case PLANT:
				if (crop != null)
				{
					items.add(crop.getPlantItemId());
				}
				break;
			case COMPOST:
				final Compost compost = settings.getRunConfig().getCompost().get(currentPatch.getType());
				if (compost != null && compost != Compost.NONE)
				{
					items.add(compost.getItemId());
				}
				items.add(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED);
				break;
			case RAKE:
				items.add(ItemID.RAKE);
				break;
			case CLEAR_DEAD:
			case DIG_STUMP:
				items.add(ItemID.SPADE);
				break;
			case CHOP:
				for (int axe : SupplyItems.AXES)
				{
					items.add(axe);
				}
				break;
			case CURE:
				items.add(ItemID.PLANT_CURE);
				break;
			case PAY:
				gardener = true;
				if (crop != null && crop.hasPayment())
				{
					items.add(crop.getPaymentItemId());
					items.add(runService.notedId(crop.getPaymentItemId()));
				}
				break;
			case PAY_TO_CLEAR:
				gardener = true;
				items.add(ItemID.COINS);
				break;
			default:
				break;
		}
		return new Highlights(currentPatch, gardener && currentPatch.hasGardener(), items);
	}

	private void travelItems(TravelMethod method, Set<Integer> items)
	{
		if (method.getItem() != null)
		{
			for (int id : method.getItem().getItemIds())
			{
				items.add(id);
			}
		}
		final Spell spell = method.getSpell();
		if (spell != null && spell.hasTablet())
		{
			items.add(spell.getTabletItemId());
		}
	}

	/** e.g. "Drop 4 weeds and 2 empty plant pots", or null when there's nothing to drop or it's turned off. */
	private String dropReminder()
	{
		if (!settings.getRunConfig().isRemindToDrop())
		{
			return null;
		}
		final Map<Integer, Integer> inventory = holdingsTracker.getHoldings().in(Holdings.Source.INVENTORY);
		final int weeds = inventory.getOrDefault(ItemID.WEEDS, 0);
		final int pots = inventory.getOrDefault(ItemID.PLANTPOT_EMPTY, 0);
		final int buckets = inventory.getOrDefault(ItemID.BUCKET_EMPTY, 0);
		final List<String> parts = new ArrayList<>();
		if (weeds > 0)
		{
			parts.add(weeds + (weeds == 1 ? " weed" : " weeds"));
		}
		if (pots > 0)
		{
			parts.add(pots + (pots == 1 ? " empty plant pot" : " empty plant pots"));
		}
		if (buckets > 0)
		{
			parts.add(buckets + (buckets == 1 ? " empty bucket" : " empty buckets"));
		}
		if (parts.isEmpty())
		{
			return null;
		}
		String text = parts.get(0);
		for (int i = 1; i < parts.size(); i++)
		{
			text += (i == parts.size() - 1 ? " and " : ", ") + parts.get(i);
		}
		return "Drop " + text;
	}

	/** Reminders shown under the step, one per line, or null when there are none. */
	private String reminders(Highlights highlights)
	{
		final List<String> lines = new ArrayList<>();
		final String missing = missingItemReminder(highlights);
		if (missing != null)
		{
			lines.add(missing);
		}
		final String drop = dropReminder();
		if (drop != null)
		{
			lines.add(drop);
		}
		final String space = spaceReminder();
		if (space != null)
		{
			lines.add(space);
		}
		return lines.isEmpty() ? null : String.join("\n", lines);
	}

	/**
	 * The item the current patch step needs isn't carried: take it from the tool leprechaun if it's stored
	 * there, otherwise say it's missing.
	 */
	private String missingItemReminder(Highlights highlights)
	{
		if (currentPatch == null || currentAction == null)
		{
			return null;
		}
		final Set<Integer> needed = highlights.getItemIds();
		if (needed.isEmpty())
		{
			return null;
		}
		final Holdings holdings = holdingsTracker.getHoldings();
		final Map<Integer, Integer> inventory = holdings.in(Holdings.Source.INVENTORY);
		final Map<Integer, Integer> worn = holdings.in(Holdings.Source.WORN);
		final Map<Integer, Integer> leprechaun = holdings.in(Holdings.Source.LEPRECHAUN);
		Integer stored = null;
		for (int id : needed)
		{
			if (inventory.getOrDefault(id, 0) > 0 || worn.getOrDefault(id, 0) > 0)
			{
				return null;
			}
			if (stored == null && leprechaun.getOrDefault(id, 0) > 0)
			{
				stored = id;
			}
		}
		if (stored != null)
		{
			final String name = runService.itemName(stored).toLowerCase();
			final String article = currentAction == StepAdvisor.Action.COMPOST ? ""
				: "aeiou".indexOf(name.charAt(0)) >= 0 ? "an " : "a ";
			return "Take " + article + name + " from the tool leprechaun";
		}
		if (currentAction == StepAdvisor.Action.CHOP)
		{
			return "You aren't carrying an axe";
		}
		// The step's main item is listed first
		return "You aren't carrying: " + runService.itemName(needed.iterator().next());
	}

	/**
	 * Not enough free inventory space for what's about to be picked here (SPEC 11.5). Herbs and fruit can be
	 * noted by the tool leprechaun at every patch.
	 */
	private String spaceReminder()
	{
		if (currentPatch == null || currentAction == null)
		{
			return null;
		}
		final PatchPrediction live = patchTracker.predict(currentPatch);
		final int expected = expectedHarvest(currentPatch, currentAction, live);
		if (expected == 0)
		{
			return null;
		}
		final int free = freeInventorySlots();
		if (free >= expected)
		{
			return null;
		}
		return "Only " + free + " free slot" + (free == 1 ? "" : "s") + ": note produce on the tool leprechaun";
	}

	/** Inventory slots the next harvest here will take (herbs and fruit), 0 if none. */
	static int expectedHarvest(Patch patch, StepAdvisor.Action action, PatchPrediction live)
	{
		if (patch.getType() == PatchType.HERB)
		{
			return action == StepAdvisor.Action.PICK ? SupplyCalculator.HERBS_PER_PATCH : 0;
		}
		if (patch.getType() == PatchType.FRUIT_TREE)
		{
			if (action == StepAdvisor.Action.PICK && live != null)
			{
				return live.getStage();
			}
			return action == StepAdvisor.Action.CHECK_HEALTH ? SupplyCalculator.FRUIT_PER_TREE : 0;
		}
		return 0;
	}

	private int freeInventorySlots()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return INVENTORY_SLOTS;
		}
		int used = 0;
		for (Item item : inventory.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				used++;
			}
		}
		return INVENTORY_SLOTS - used;
	}

	private RunView idleView()
	{
		final RunPlan current = runService.getPlan();
		final boolean ready = isReady(current);
		String notice = null;
		if (lastRun != null && System.currentTimeMillis() - finishedAt < FINISHED_NOTICE_MILLIS)
		{
			notice = lastRun;
		}
		else if (ready)
		{
			notice = "Ready - press Start run";
		}
		return new RunView(RunView.State.IDLE, 0, new ArrayList<>(), notice, ready, lastRun, bestTimes(current),
			null, Highlights.NONE);
	}

	/**
	 * Everything required is carried, or can be taken from the tool leprechaun when the run starts (every
	 * location has one).
	 */
	static boolean isReady(RunPlan plan)
	{
		if (plan.getRoute().getStops().isEmpty())
		{
			return false;
		}
		for (SupplyLine line : plan.getSupplies().getLines())
		{
			if (line.getGroup() == SupplyLine.Group.OPTIONAL || line.isCoveredOtherwise())
			{
				continue;
			}
			final int leprechaun = line.getWhere().getOrDefault(Holdings.Source.LEPRECHAUN, 0);
			if (line.getCarried() + leprechaun < line.getNeed())
			{
				return false;
			}
		}
		return true;
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.route.LearnedTimes;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Saves how long each leg and run took, per account (SPEC 12.4). Milestone M8 uses these to replace the
 * starting time estimates with the player's own.
 */
@Slf4j
@Singleton
public class RunTimings
{
	private static final String LEGS_KEY = "timings.legs";
	private static final String RUNS_KEY = "timings.runs";
	/** Keep the most recent samples only. */
	private static final int MAX_LEGS = 500;
	private static final int MAX_RUNS = 100;

	/** No-argument constructor so Gson can build these normally. */
	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Leg
	{
		/** Location enum name. */
		String location;
		/** TravelMethod enum name, or null for walking and for the trip to the first stop. */
		String method;
		/** Departure enum name. */
		String departure;
		double seconds;
		long finishedAt;
	}

	@Data
	@NoArgsConstructor
	@AllArgsConstructor
	public static class Run
	{
		long startedAt;
		double seconds;
		int stops;
		boolean finished;
		/** Patches by type, e.g. "HERB:6,TREE:6", so runs are only compared with like runs. Null in old saves. */
		String makeup;
	}

	private final ConfigManager configManager;
	private final Gson gson;
	/** Saved runs and learned leg times for {@link #cachedProfile}, so they aren't re-read every tick. */
	private List<Run> cachedRuns;
	private LearnedTimes cachedLearned;
	private String cachedProfile;

	@Inject
	RunTimings(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void save(List<Leg> legs, Run run)
	{
		final List<Leg> savedLegs = read(LEGS_KEY, Leg[].class);
		savedLegs.addAll(legs);
		write(LEGS_KEY, trim(savedLegs, MAX_LEGS));

		final List<Run> savedRuns = read(RUNS_KEY, Run[].class);
		savedRuns.add(run);
		write(RUNS_KEY, trim(savedRuns, MAX_RUNS));
		cachedRuns = null;
		cachedLearned = null;
	}

	/** The fastest finished runs with this makeup, quickest first, at most {@code limit}. */
	public List<Double> best(String makeup, int limit)
	{
		checkProfile();
		if (cachedRuns == null)
		{
			cachedRuns = read(RUNS_KEY, Run[].class);
		}
		return best(cachedRuns, makeup, limit);
	}

	/** The player's recorded times for each way of reaching each stop. */
	public LearnedTimes learned()
	{
		checkProfile();
		if (cachedLearned == null)
		{
			cachedLearned = learned(read(LEGS_KEY, Leg[].class));
		}
		return cachedLearned;
	}

	public static LearnedTimes learned(List<Leg> legs)
	{
		final Map<String, List<Double>> samples = new HashMap<>();
		for (Leg leg : legs)
		{
			// The trip to the first stop and walks between stops aren't samples of a travel method
			if (leg.getMethod() != null && leg.getDeparture() != null && leg.getLocation() != null)
			{
				samples.computeIfAbsent(LearnedTimes.key(leg.getLocation(), leg.getMethod(), leg.getDeparture()),
					k -> new ArrayList<>()).add(leg.getSeconds());
			}
		}
		return new LearnedTimes(samples);
	}

	private void checkProfile()
	{
		final String profile = configManager.getRSProfileKey();
		if (!Objects.equals(profile, cachedProfile))
		{
			cachedRuns = null;
			cachedLearned = null;
			cachedProfile = profile;
		}
	}

	static List<Double> best(List<Run> runs, String makeup, int limit)
	{
		final List<Double> times = new ArrayList<>();
		for (Run run : runs)
		{
			if (run.isFinished() && makeup.equals(run.getMakeup()))
			{
				times.add(run.getSeconds());
			}
		}
		Collections.sort(times);
		return times.size() <= limit ? times : new ArrayList<>(times.subList(0, limit));
	}

	/** e.g. "HERB:6,TREE:6", in patch type order. */
	public static String makeup(Map<PatchType, Integer> counts)
	{
		final List<String> parts = new ArrayList<>();
		for (PatchType type : PatchType.values())
		{
			final int n = counts.getOrDefault(type, 0);
			if (n > 0)
			{
				parts.add(type.name() + ":" + n);
			}
		}
		return String.join(",", parts);
	}

	/** e.g. "6 herbs, 6 trees". */
	public static String makeupName(Map<PatchType, Integer> counts)
	{
		final List<String> parts = new ArrayList<>();
		for (PatchType type : PatchType.values())
		{
			final int n = counts.getOrDefault(type, 0);
			if (n > 0)
			{
				parts.add(n + " " + type.getDisplayName().toLowerCase() + (n == 1 ? "" : "s"));
			}
		}
		return String.join(", ", parts);
	}

	public List<Leg> legs()
	{
		return read(LEGS_KEY, Leg[].class);
	}

	/** Stored as JSON arrays, so plain array classes are enough for Gson (no type tokens needed). */
	private <T> List<T> read(String key, Class<T[]> type)
	{
		final String json = configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
		if (json == null)
		{
			return new ArrayList<>();
		}
		try
		{
			final T[] items = gson.fromJson(json, type);
			return items != null ? new ArrayList<>(Arrays.asList(items)) : new ArrayList<>();
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved {}", key, e);
			return new ArrayList<>();
		}
	}

	private void write(String key, Object value)
	{
		if (configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, gson.toJson(value));
		}
	}

	private static <T> List<T> trim(List<T> list, int max)
	{
		return list.size() <= max ? list : new ArrayList<>(list.subList(list.size() - max, list.size()));
	}
}

package com.farmrunautopilot.run;

import java.util.Collections;
import java.util.List;
import lombok.Value;

/**
 * A snapshot of the run session for the sidebar and overlay. Immutable; safe to pass between threads.
 */
@Value
public class RunView
{
	public enum State
	{
		IDLE,
		RUNNING
	}

	public enum StopStatus
	{
		DONE,
		CURRENT,
		PENDING
	}

	@Value
	public static class Stop
	{
		String location;
		String travel;
		StopStatus status;
		/** What to do there right now (current stop only), else null. */
		String instruction;
		/** The plan for each patch there, for hovering. */
		List<String> objectives;
	}

	public static final RunView IDLE_VIEW = new RunView(State.IDLE, 0, Collections.emptyList(), null, false, null,
		null, null, Highlights.NONE);

	State state;
	/** When the run started (epoch millis), 0 when idle. */
	long startedAtMillis;
	List<Stop> stops;
	/** The next thing to do, shown under the player, or null. */
	String instruction;
	/** Everything needed is in the inventory, so the run can start. */
	boolean ready;
	/** e.g. "Run finished in 12:30", or null. */
	String lastRun;
	/** e.g. "Best for 6 herbs: 8:12, 8:40, 9:03", or null when there are none yet. */
	String bestTimes;
	/** Reminders under the instruction, one per line (e.g. "Drop 4 weeds"), or null. */
	String reminder;
	Highlights highlights;
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchPoints;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.coords.WorldPoint;

/**
 * Keeps the loaded patch objects and gardener NPCs, for highlighting. Driven by spawn and despawn events,
 * never by scanning the scene. Client thread only.
 *
 * <p>A patch object is recognised by the varbit that drives it (the patch's own FARMING_TRANSMIT varbit)
 * near the patch's map point, so every look of every patch matches without an ID list.
 */
@Slf4j
@Singleton
public class SceneTracker
{
	/**
	 * How far a patch object can be from its {@link PatchPoints} entry. Generous, because some points are a few
	 * tiles off (one was on the neighbouring flower patch); other patches nearby (flowers, allotments) use
	 * different varbits, so they never match.
	 */
	private static final int PATCH_SEARCH_TILES = 30;
	/** Gardeners wander a little around their patch. */
	private static final int GARDENER_TILES = 20;

	private final Client client;
	private final Map<Patch, List<GameObject>> patchObjects = new EnumMap<>(Patch.class);
	private final Map<Patch, NPC> gardeners = new EnumMap<>(Patch.class);

	@Inject
	SceneTracker(Client client)
	{
		this.client = client;
	}

	public void onObjectSpawned(GameObject object)
	{
		final Patch patch = patchFor(object);
		if (patch != null)
		{
			final List<GameObject> objects = patchObjects.computeIfAbsent(patch, k -> new ArrayList<>());
			if (objects.isEmpty())
			{
				// For checking PatchPoints against where patches really are
				log.debug("Patch object for {} at {} (map point {}, {} tiles off)", patch, object.getWorldLocation(),
					PatchPoints.of(patch), PatchPoints.of(patch).distanceTo2D(object.getWorldLocation()));
			}
			objects.add(object);
		}
	}

	public void onObjectDespawned(GameObject object)
	{
		for (List<GameObject> objects : patchObjects.values())
		{
			objects.remove(object);
		}
	}

	/**
	 * Gardeners are matched by name as well as ID, because some have several IDs (Treznor has three), and only
	 * near their own patch.
	 */
	public void onNpcSpawned(NPC npc)
	{
		final WorldPoint location = npc.getWorldLocation();
		for (Patch patch : Patch.values())
		{
			if (!patch.hasGardener())
			{
				continue;
			}
			final boolean same = patch.getGardenerNpcId() == npc.getId() || patch.getGardenerName().equals(npc.getName());
			final WorldPoint point = PatchPoints.of(patch);
			if (same && point.getPlane() == location.getPlane() && point.distanceTo2D(location) <= GARDENER_TILES)
			{
				gardeners.put(patch, npc);
				return;
			}
		}
	}

	public void onNpcDespawned(NPC npc)
	{
		gardeners.values().removeIf(n -> n == npc);
	}

	/**
	 * The scene is reloading: objects are spawned again afterwards, but NPCs already nearby are not, so the
	 * gardeners are kept (they're removed when they despawn).
	 */
	public void clearObjects()
	{
		patchObjects.clear();
	}

	/** Logged out or hopping: nothing is loaded any more. */
	public void clear()
	{
		patchObjects.clear();
		gardeners.clear();
	}

	public List<GameObject> objectsFor(Patch patch)
	{
		final List<GameObject> objects = patchObjects.get(patch);
		return objects != null ? objects : Collections.emptyList();
	}

	/** The patch's gardener if loaded, or null. */
	public NPC gardener(Patch patch)
	{
		return gardeners.get(patch);
	}

	private Patch patchFor(GameObject object)
	{
		final WorldPoint location = object.getWorldLocation();
		ObjectComposition composition = null;
		Patch best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (Map.Entry<Patch, WorldPoint> e : PatchPoints.all().entrySet())
		{
			final WorldPoint point = e.getValue();
			final int distance = point.getPlane() == location.getPlane() ? point.distanceTo2D(location)
				: Integer.MAX_VALUE;
			if (distance > PATCH_SEARCH_TILES || distance >= bestDistance)
			{
				continue;
			}
			// Only look the object up once it's near a patch
			if (composition == null)
			{
				composition = client.getObjectDefinition(object.getId());
				if (composition == null || composition.getImpostorIds() == null)
				{
					return null;
				}
			}
			if (composition.getVarbitId() == e.getKey().getVarbitId())
			{
				best = e.getKey();
				bestDistance = distance;
			}
		}
		return best;
	}

	/** Where the patch really is: its loaded object if there is one, otherwise its map point. */
	public WorldPoint locationOf(Patch patch)
	{
		final List<GameObject> objects = objectsFor(patch);
		return objects.isEmpty() ? PatchPoints.of(patch) : objects.get(0).getWorldLocation();
	}
}

package com.farmrunautopilot.run;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.tracking.PatchPrediction;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * What to do next at a patch, worked out from its live state (SPEC 13.4). Working from the state rather
 * than a fixed checklist means the guide keeps up if the player does things in another order or the game
 * does them (a gardener clearing a tree, weeds growing back).
 */
public final class StepAdvisor
{
	public enum Action
	{
		/** No data for the patch yet; walk up to it. */
		INSPECT,
		RAKE,
		CLEAR_DEAD,
		CURE,
		CHECK_HEALTH,
		PICK,
		PAY_TO_CLEAR,
		CHOP,
		DIG_STUMP,
		COMPOST,
		PLANT,
		PAY,
		DONE
	}

	@Value
	public static class Advice
	{
		Action action;
		String text;
	}

	/** What the run plan wants at a patch, and what has happened there this run. */
	@Value
	public static class PatchGoal
	{
		Patch patch;
		Crop crop;
		/** Seed or sapling item name, e.g. "Ranarr seed". */
		String plantName;
		Compost compost;
		/** The gardener must be paid for this patch. */
		boolean protectionNeeded;
		/** e.g. "25 x Coconut (noted is fine)". */
		String paymentText;
		boolean payToClear;
		boolean composted;
		boolean paid;
		/** Seen empty, ready or dead during this run, so a growing crop was planted this run. */
		boolean plantedThisRun;
	}

	private StepAdvisor()
	{
	}

	public static Advice advise(PatchGoal goal, PatchPrediction live)
	{
		final Patch patch = goal.getPatch();
		if (live == null)
		{
			return new Advice(Action.INSPECT, "Walk to the " + patch.getDisplayName() + " patch");
		}
		final String gardener = patch.getGardenerName() != null ? patch.getGardenerName() : "the gardener";
		final String what = live.getCrop() != null ? live.getCrop().getDisplayName().toLowerCase() : "plant";
		final boolean tree = patch.getType().isProtectable();

		switch (live.getState())
		{
			case GROWING:
				// Only ask for payment if it was planted this run; otherwise it was already growing.
				if (goal.isPlantedThisRun() && goal.isProtectionNeeded() && !goal.isPaid())
				{
					return new Advice(Action.PAY, "Pay " + gardener + ": " + goal.getPaymentText());
				}
				return new Advice(Action.DONE, "Done");
			case CHECK_HEALTH:
				return new Advice(Action.CHECK_HEALTH, "Check the health of the " + (live.getCrop() != null
					? what + " tree" : patch.getType().getDisplayName().toLowerCase()) + " (replanting: "
					+ goal.getPlantName() + ")");
			case HARVESTABLE:
				if (patch.getType() == PatchType.HERB)
				{
					return new Advice(Action.PICK, "Pick the " + what);
				}
				if (patch.getType() == PatchType.FRUIT_TREE && live.getStage() > 0)
				{
					return new Advice(Action.PICK, "Pick the " + what + " fruit (" + live.getStage() + " left)");
				}
				return clearTree(goal, gardener);
			case STUMP:
				return goal.isPayToClear()
					? new Advice(Action.PAY_TO_CLEAR, "Ask " + gardener + " to remove the stump (200 coins)")
					: new Advice(Action.DIG_STUMP, "Dig up the stump with your spade");
			case DEAD:
				return new Advice(Action.CLEAR_DEAD, "Clear the dead " + what + (tree ? " tree" : "") + " (spade)");
			case DISEASED:
				return new Advice(Action.CURE, "Cure the diseased " + what + " with plant cure, or clear it");
			case WEEDS:
				return new Advice(Action.RAKE, "Rake the patch");
			case EMPTY:
				if (goal.getCompost() != null && goal.getCompost() != Compost.NONE && !goal.isComposted())
				{
					return new Advice(Action.COMPOST, "Use " + goal.getCompost().getDisplayName().toLowerCase()
						+ " on the patch");
				}
				return new Advice(Action.PLANT, "Plant: " + goal.getPlantName());
			default:
				return new Advice(Action.INSPECT, "Inspect the patch");
		}
	}

	/**
	 * A short plan for a patch, for hovering a route stop, e.g. "Herb: harvest guam and plant ranarr" or
	 * "Fruit tree: check health of papaya, clear and plant papaya".
	 *
	 * @param live what's in the patch now, or null if unknown
	 * @param plant what to plant, or null if not decided
	 */
	public static String objectives(Patch patch, PatchPrediction live, Crop plant)
	{
		final List<String> steps = new ArrayList<>();
		final boolean tree = patch.getType() == PatchType.TREE || patch.getType() == PatchType.FRUIT_TREE;
		boolean replant = true;
		if (live == null)
		{
			steps.add("check the patch");
		}
		else
		{
			final String what = live.getCrop() != null ? live.getCrop().getDisplayName().toLowerCase() : "the crop";
			switch (live.getState())
			{
				case GROWING:
					steps.add(what + " still growing");
					replant = false;
					break;
				case CHECK_HEALTH:
					steps.add("check health of " + what);
					if (tree)
					{
						steps.add("clear");
					}
					break;
				case HARVESTABLE:
					if (patch.getType() == PatchType.FRUIT_TREE)
					{
						steps.add((live.getStage() > 0 ? "pick " : "") + what);
						steps.add("clear");
					}
					else
					{
						steps.add((tree ? "clear " : "harvest ") + what);
					}
					break;
				case STUMP:
					steps.add("clear the stump");
					break;
				case DEAD:
					steps.add("clear dead " + what);
					break;
				case DISEASED:
					steps.add("cure or clear " + what);
					break;
				case WEEDS:
					steps.add("rake");
					break;
				default:
					break;
			}
		}
		if (replant)
		{
			steps.add("plant " + (plant != null ? plant.getDisplayName().toLowerCase() : "a seed"));
		}
		String text = steps.get(0);
		for (int i = 1; i < steps.size(); i++)
		{
			text += (i == steps.size() - 1 ? " and " : ", ") + steps.get(i);
		}
		return patch.getType().getDisplayName() + ": " + text;
	}

	private static Advice clearTree(PatchGoal goal, String gardener)
	{
		return goal.isPayToClear()
			? new Advice(Action.PAY_TO_CLEAR, "Ask " + gardener + " to remove the tree (200 coins)")
			: new Advice(Action.CHOP, "Chop down the tree");
	}
}

