package com.farmrunautopilot.settings;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.data.travel.TravelMethod;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Data;

/**
 * Everything the player chooses for a run (SPEC 5 RunConfig). Saved as JSON per account; milestone M9
 * turns it into named presets. Fields are mutable so Gson can fill them; call {@link #sanitise()}
 * after loading.
 */
@Data
public class RunConfig
{
	public static final int DEFAULT_DUE_THRESHOLD = 100;
	/** 2nd and 3rd choice. */
	public static final int MAX_BACKUP_CROPS = 2;

	// Run types
	private Set<PatchType> enabledTypes = EnumSet.allOf(PatchType.class);
	/** Include a run type when at least this percent of its patches are due (SPEC 10). */
	private int dueThresholdPercent = DEFAULT_DUE_THRESHOLD;

	// Patches and crops
	/** Patches the player unticked. A manual untick always wins over detection. */
	private Set<Patch> disabledPatches = EnumSet.noneOf(Patch.class);
	/** Chosen (1st choice) crop per run type; a missing entry means "highest my Farming level allows". */
	private Map<PatchType, Crop> crops = new EnumMap<>(PatchType.class);
	/** Plant 2nd/3rd choices when the player runs out of the 1st (changed from the spec's single choice). */
	private boolean useBackupCrops = false;
	/** 2nd and 3rd choice per run type, in order. */
	private Map<PatchType, List<Crop>> backupCrops = new EnumMap<>(PatchType.class);
	/** Use {@link #diseaseFreeHerbs}; when off the list is kept but ignored. */
	private boolean prioritiseDiseaseFreeHerbs = false;
	/**
	 * Herbs reserved for disease-free patches: those patches get these first (most valuable first) and other
	 * patches never get them.
	 */
	private Set<Crop> diseaseFreeHerbs = EnumSet.noneOf(Crop.class);

	// Protection
	private Map<PatchType, Protection> protection = defaultProtection();
	private Map<Patch, Protection> protectionOverrides = new EnumMap<>(Patch.class);
	/** Bring gardener payments noted (one slot each); confirmed preferable in-game. */
	private boolean payWithNotes = true;
	/** Run types where the gardener is paid 200 coins to clear a grown tree instead of chopping it. */
	private Set<PatchType> payToClear = EnumSet.of(PatchType.TREE, PatchType.FRUIT_TREE);
	private Map<PatchType, Compost> compost = defaultCompost();
	private int plantCureDoses = 0;
	private boolean useCurePlant = false;
	private boolean useResurrectCrops = false;
	/** Suggest magic secateurs and Farming cape/outfit as optional items. */
	private boolean recommendEquipmentBoosts = true;

	// Travel
	/** Chosen method per location; a missing entry means "Auto (best)". */
	private Map<Location, TravelMethod> travel = new EnumMap<>(Location.class);
	private boolean useRunesNotTabs = false;
	private Set<Location> runesNotTabsAt = EnumSet.noneOf(Location.class);

	// Route
	private RouteMode routeMode = RouteMode.AUTOPILOT;
	private List<Location> customOrder = new ArrayList<>();
	private Location startLocation = Location.FARMING_GUILD;
	private boolean endNearBank = true;
	private int staminaDoses = 0;
	private Outfit outfit = Outfit.NONE;
	/** During a run, remind the player to drop weeds and empty plant pots. */
	private boolean remindToDrop = true;
	/** Walk instead of teleporting when the walk is only a little slower (saves charges and clicks). */
	private boolean preferWalking = true;

	// Run tab
	/** Supplies for every selected patch instead of only the due ones. */
	private boolean supplyFullRun = false;

	// Storage sources (SPEC 2: both default off)
	private boolean useGroupStorage = false;
	private boolean useSeedVault = false;

	/**
	 * Fills in anything Gson left null (new fields, or enum names that no longer exist) and clamps
	 * numbers to sensible ranges.
	 */
	public RunConfig sanitise()
	{
		enabledTypes = cleanSet(enabledTypes, PatchType.class, EnumSet.allOf(PatchType.class));
		disabledPatches = cleanSet(disabledPatches, Patch.class, EnumSet.noneOf(Patch.class));
		payToClear = cleanSet(payToClear, PatchType.class, EnumSet.noneOf(PatchType.class));
		runesNotTabsAt = cleanSet(runesNotTabsAt, Location.class, EnumSet.noneOf(Location.class));

		crops = cleanMap(crops, PatchType.class);
		crops.entrySet().removeIf(e -> e.getValue().getType() != e.getKey());
		backupCrops = cleanMap(backupCrops, PatchType.class);
		backupCrops.replaceAll((type, list) -> cleanBackups(type, list));
		diseaseFreeHerbs = cleanSet(diseaseFreeHerbs, Crop.class, EnumSet.noneOf(Crop.class));
		diseaseFreeHerbs.removeIf(c -> c.getType() != PatchType.HERB);
		protectionOverrides = cleanMap(protectionOverrides, Patch.class);
		travel = cleanMap(travel, Location.class);
		travel.entrySet().removeIf(e -> e.getValue().getDestination() != e.getKey());

		final Map<PatchType, Protection> protectionDefaults = defaultProtection();
		protection = cleanMap(protection, PatchType.class);
		protectionDefaults.forEach(protection::putIfAbsent);
		final Map<PatchType, Compost> compostDefaults = defaultCompost();
		compost = cleanMap(compost, PatchType.class);
		compostDefaults.forEach(compost::putIfAbsent);

		if (customOrder == null)
		{
			customOrder = new ArrayList<>();
		}
		customOrder.removeIf(l -> l == null);
		if (outfit == null)
		{
			outfit = Outfit.NONE;
		}
		if (routeMode == null)
		{
			routeMode = RouteMode.AUTOPILOT;
		}
		if (startLocation == null)
		{
			startLocation = Location.FARMING_GUILD;
		}

		dueThresholdPercent = clamp(dueThresholdPercent, 1, 100);
		staminaDoses = clamp(staminaDoses, 0, 40);
		plantCureDoses = clamp(plantCureDoses, 0, 40);
		return this;
	}

	public boolean isPatchSelected(Patch patch)
	{
		return enabledTypes.contains(patch.getType()) && !disabledPatches.contains(patch);
	}

	public Protection protectionFor(Patch patch)
	{
		final Protection override = protectionOverrides.get(patch);
		return override != null ? override : protection.get(patch.getType());
	}

	/**
	 * The chosen crop, or the highest one {@code farmingLevel} can plant (the lowest if none).
	 */
	public Crop cropFor(PatchType type, int farmingLevel)
	{
		final Crop chosen = crops.get(type);
		if (chosen != null)
		{
			return chosen;
		}
		Crop best = null;
		for (Crop crop : Crop.values())
		{
			if (crop.getType() == type && (best == null || crop.getFarmingLevel() <= farmingLevel))
			{
				best = crop;
			}
		}
		return best;
	}

	/**
	 * The crops to plant for a run type, best first: the 1st choice, then the backups the player can plant
	 * (only when backups are switched on).
	 */
	public List<Crop> cropChoices(PatchType type, int farmingLevel)
	{
		final List<Crop> choices = new ArrayList<>();
		choices.add(cropFor(type, farmingLevel));
		if (useBackupCrops)
		{
			for (Crop crop : backupCrops.getOrDefault(type, Collections.emptyList()))
			{
				if (crop.getFarmingLevel() <= farmingLevel && !choices.contains(crop))
				{
					choices.add(crop);
				}
			}
		}
		return choices;
	}

	public boolean useRunesAt(Location location)
	{
		return useRunesNotTabs || runesNotTabsAt.contains(location);
	}

	private static Map<PatchType, Protection> defaultProtection()
	{
		final Map<PatchType, Protection> map = new EnumMap<>(PatchType.class);
		map.put(PatchType.TREE, Protection.PAY_GARDENER);
		map.put(PatchType.FRUIT_TREE, Protection.PAY_GARDENER);
		return map;
	}

	private static Map<PatchType, Compost> defaultCompost()
	{
		final Map<PatchType, Compost> map = new EnumMap<>(PatchType.class);
		map.put(PatchType.TREE, Compost.NONE);
		map.put(PatchType.FRUIT_TREE, Compost.NONE);
		map.put(PatchType.HERB, Compost.ULTRACOMPOST);
		return map;
	}

	private static List<Crop> cleanBackups(PatchType type, List<Crop> list)
	{
		final List<Crop> clean = new ArrayList<>();
		for (Crop crop : list)
		{
			if (crop != null && crop.getType() == type && !clean.contains(crop) && clean.size() < MAX_BACKUP_CROPS)
			{
				clean.add(crop);
			}
		}
		return clean;
	}

	static <E extends Enum<E>> Set<E> cleanSet(Set<E> set, Class<E> type, Set<E> fallback)
	{
		if (set == null)
		{
			return fallback;
		}
		final Set<E> clean = EnumSet.noneOf(type);
		for (E e : set)
		{
			if (e != null)
			{
				clean.add(e);
			}
		}
		return clean;
	}

	static <K extends Enum<K>, V> Map<K, V> cleanMap(Map<K, V> map, Class<K> type)
	{
		final Map<K, V> clean = new EnumMap<>(type);
		if (map != null)
		{
			map.forEach((k, v) ->
			{
				if (k != null && v != null)
				{
					clean.put(k, v);
				}
			});
		}
		return clean;
	}

	private static int clamp(int value, int min, int max)
	{
		return Math.max(min, Math.min(max, value));
	}
}

package com.farmrunautopilot.settings;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Loads and saves {@link RunConfig} and {@link AccountSettings} as JSON in the current account's RuneLite
 * profile (SPEC 14). Edits made while logged out stay in memory only.
 */
@Slf4j
@Singleton
public class SettingsStore
{
	private static final String RUN_CONFIG_KEY = "runConfig";
	private static final String ACCOUNT_KEY = "account";
	private static final String OPEN_SECTIONS_KEY = "ui.openSections";
	private static final String PRESETS_KEY = "presets";
	/** Open the first time: the ones changed most often. */
	private static final List<String> DEFAULT_OPEN_SECTIONS = Arrays.asList("Crops", "Run options");

	private final ConfigManager configManager;
	private final Gson gson;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();
	private final List<Runnable> saveListeners = new CopyOnWriteArrayList<>();

	@Getter
	private volatile RunConfig runConfig = new RunConfig();
	@Getter
	private volatile AccountSettings account = new AccountSettings();
	/** Replaced, never changed in place. */
	private volatile List<Preset> presets = new ArrayList<>();

	@Inject
	SettingsStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** Called after settings are reloaded or changed by something other than the Setup tab. */
	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public void removeListener(Runnable listener)
	{
		listeners.remove(listener);
	}

	/** Called after every save and reload, e.g. so the supply plan is recalculated. */
	public void addSaveListener(Runnable listener)
	{
		saveListeners.add(listener);
	}

	public void removeSaveListener(Runnable listener)
	{
		saveListeners.remove(listener);
	}

	/**
	 * Whether a sidebar section is open. Stored once for the whole client (not per account), as a
	 * comma-separated list of open section titles.
	 */
	public boolean isSectionOpen(String title)
	{
		final String open = configManager.getConfiguration(FarmRunAutopilotConfig.GROUP, OPEN_SECTIONS_KEY);
		if (open == null)
		{
			return DEFAULT_OPEN_SECTIONS.contains(title);
		}
		return Arrays.asList(open.split(",")).contains(title);
	}

	public void setSectionOpen(String title, boolean isOpen)
	{
		final String saved = configManager.getConfiguration(FarmRunAutopilotConfig.GROUP, OPEN_SECTIONS_KEY);
		final Set<String> open = new LinkedHashSet<>(saved == null ? DEFAULT_OPEN_SECTIONS
			: Arrays.asList(saved.split(",")));
		open.remove("");
		if (isOpen)
		{
			open.add(title);
		}
		else
		{
			open.remove(title);
		}
		configManager.setConfiguration(FarmRunAutopilotConfig.GROUP, OPEN_SECTIONS_KEY, String.join(",", open));
	}

	/** Whether there is an account profile to save to (i.e. the player has logged in). */
	public boolean hasProfile()
	{
		return configManager.getRSProfileKey() != null;
	}

	/** Reloads everything from the current profile, e.g. after login or switching accounts. */
	public void load()
	{
		runConfig = read(RUN_CONFIG_KEY, RunConfig.class, new RunConfig()).sanitise();
		account = read(ACCOUNT_KEY, AccountSettings.class, new AccountSettings()).sanitise();
		final List<Preset> loaded = new ArrayList<>();
		for (Preset preset : read(PRESETS_KEY, Preset[].class, new Preset[0]))
		{
			if (preset != null && preset.getName() != null && preset.getConfig() != null)
			{
				preset.getConfig().sanitise();
				loaded.add(preset);
			}
		}
		presets = loaded;
		notifyListeners();
		for (Runnable listener : saveListeners)
		{
			listener.run();
		}
	}

	public void saveRunConfig()
	{
		write(RUN_CONFIG_KEY, runConfig);
	}

	// Presets (SPEC 13.5). Swing thread.

	public List<String> presetNames()
	{
		final List<String> names = new ArrayList<>();
		for (Preset preset : presets)
		{
			names.add(preset.getName());
		}
		return names;
	}

	/** The preset the current settings match exactly, or null if they've been changed since. */
	public String activePreset()
	{
		for (Preset preset : presets)
		{
			if (preset.getConfig().equals(runConfig))
			{
				return preset.getName();
			}
		}
		return null;
	}

	/** Save the current settings under this name, replacing a preset with the same name. */
	public void savePreset(String name)
	{
		final List<Preset> updated = new ArrayList<>(presets);
		final Preset preset = new Preset(name, copy(runConfig));
		final int index = indexOf(name);
		if (index >= 0)
		{
			updated.set(index, preset);
		}
		else
		{
			updated.add(preset);
		}
		writePresets(updated);
	}

	/** Switch the current settings to this preset. */
	public void applyPreset(String name)
	{
		final int index = indexOf(name);
		if (index < 0)
		{
			return;
		}
		runConfig = copy(presets.get(index).getConfig());
		saveRunConfig();
		notifyListeners();
	}

	public void renamePreset(String from, String to)
	{
		final int index = indexOf(from);
		if (index < 0 || indexOf(to) >= 0)
		{
			return;
		}
		final List<Preset> updated = new ArrayList<>(presets);
		updated.set(index, new Preset(to, presets.get(index).getConfig()));
		writePresets(updated);
	}

	public void deletePreset(String name)
	{
		final List<Preset> updated = new ArrayList<>(presets);
		updated.removeIf(p -> p.getName().equals(name));
		writePresets(updated);
	}

	private int indexOf(String name)
	{
		for (int i = 0; i < presets.size(); i++)
		{
			if (presets.get(i).getName().equals(name))
			{
				return i;
			}
		}
		return -1;
	}

	private void writePresets(List<Preset> updated)
	{
		presets = updated;
		write(PRESETS_KEY, updated.toArray(new Preset[0]));
		notifyListeners();
	}

	/** A deep copy, so editing the current settings never changes a saved preset. */
	private RunConfig copy(RunConfig config)
	{
		return gson.fromJson(gson.toJson(config), RunConfig.class).sanitise();
	}

	/**
	 * @param external true when the change did not come from the Setup tab, so the tab must refresh
	 */
	public void saveAccount(boolean external)
	{
		write(ACCOUNT_KEY, account);
		if (external)
		{
			notifyListeners();
		}
	}

	private <T> T read(String key, Class<T> type, T fallback)
	{
		final String json = configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
		if (json == null)
		{
			return fallback;
		}
		try
		{
			final T value = gson.fromJson(json, type);
			return value != null ? value : fallback;
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read saved {}, using defaults", key, e);
			return fallback;
		}
	}

	private void write(String key, Object value)
	{
		if (hasProfile())
		{
			configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, gson.toJson(value));
		}
		for (Runnable listener : saveListeners)
		{
			listener.run();
		}
	}

	private void notifyListeners()
	{
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;

/**
 * Decides which crop goes in which patch of one run type.
 *
 * <p>Safe patches (disease-free or protected) are filled first. They take reserved crops first (e.g. the
 * player's valuable herbs for disease-free patches), then the normal choices. Other patches never get
 * reserved crops. Each patch gets the best crop still in stock; if everything has run out it gets its
 * first allowed choice, and that crop shows as short.
 */
public final class CropAllocator
{
	private CropAllocator()
	{
	}

	/**
	 * @param patches the patches of one run type in this run
	 * @param choices crops in order of preference (1st choice first)
	 * @param held how many of a crop's seed or sapling the player holds
	 * @param safe whether a patch is disease-free or protected
	 * @param reservedForSafe crops only for safe patches, best first; may be empty
	 * @return crop per patch, in the order patches were given
	 */
	public static Map<Patch, Crop> allocate(List<Patch> patches, List<Crop> choices, ToIntFunction<Crop> held,
		Predicate<Patch> safe, List<Crop> reservedForSafe)
	{
		final List<Patch> order = new ArrayList<>();
		for (Patch patch : patches)
		{
			if (safe.test(patch))
			{
				order.add(patch);
			}
		}
		for (Patch patch : patches)
		{
			if (!safe.test(patch))
			{
				order.add(patch);
			}
		}

		final Map<Crop, Integer> stock = new HashMap<>();
		for (Crop crop : choices)
		{
			stock.put(crop, held.applyAsInt(crop));
		}
		for (Crop crop : reservedForSafe)
		{
			stock.put(crop, held.applyAsInt(crop));
		}

		// Normal choices for patches that aren't safe: never a reserved crop, unless every choice is reserved.
		final List<Crop> unsafeChoices = new ArrayList<>();
		for (Crop crop : choices)
		{
			if (!reservedForSafe.contains(crop))
			{
				unsafeChoices.add(crop);
			}
		}
		if (unsafeChoices.isEmpty())
		{
			unsafeChoices.add(choices.get(0));
		}

		final Map<Patch, Crop> byPatch = new HashMap<>();
		for (Patch patch : order)
		{
			final List<Crop> candidates = new ArrayList<>();
			if (safe.test(patch))
			{
				candidates.addAll(reservedForSafe);
				candidates.addAll(choices);
			}
			else
			{
				candidates.addAll(unsafeChoices);
			}

			Crop pick = null;
			for (Crop crop : candidates)
			{
				if (stock.get(crop) > 0)
				{
					pick = crop;
					break;
				}
			}
			if (pick == null)
			{
				// Everything is out: use the first normal choice this patch may have.
				pick = safe.test(patch) ? choices.get(0) : unsafeChoices.get(0);
			}
			stock.merge(pick, -1, Integer::sum);
			byPatch.put(patch, pick);
		}

		final Map<Patch, Crop> result = new LinkedHashMap<>();
		for (Patch patch : patches)
		{
			result.put(patch, byPatch.get(patch));
		}
		return result;
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.data.travel.Rune;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import lombok.Value;

/**
 * Everything the player has, by where it is (SPEC 11). Item IDs are canonical: noted items are counted
 * as their unnoted item. Immutable; built on the client thread, read anywhere.
 */
@Value
public class Holdings
{
	public enum Source
	{
		INVENTORY("inventory"),
		WORN("worn"),
		BANK("bank"),
		LEPRECHAUN("leprechaun"),
		GROUP_STORAGE("group storage"),
		SEED_VAULT("seed vault");

		private final String label;

		Source(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	public static final Holdings EMPTY = new Holdings(Collections.emptyMap(), Collections.emptyMap(),
		Collections.emptySet(), false, false);

	/** Item counts per source. Sources that are switched off or never seen are absent. */
	Map<Source, Map<Integer, Integer>> items;
	/** Rune pouch contents by rune item (combination runes included), only when a pouch is in the inventory. */
	Map<Integer, Integer> runePouch;
	/** Runes supplied without limit by an equipped staff or tome. */
	Set<Rune> infiniteRunes;
	/** The bank has been opened at least once on this account, so its contents are known. */
	boolean bankKnown;
	/** Tithe Farm Auto-weed is owned and switched on. */
	boolean autoweedOn;

	public int count(int itemId)
	{
		int total = runePouch.getOrDefault(itemId, 0);
		for (Map<Integer, Integer> source : items.values())
		{
			total += source.getOrDefault(itemId, 0);
		}
		return total;
	}

	/** Total held of any of these items. */
	public int countAny(int[] itemIds)
	{
		int total = 0;
		for (int id : itemIds)
		{
			total += count(id);
		}
		return total;
	}

	/** Where these items are, e.g. {BANK=12, INVENTORY=3}. Rune pouch contents count as inventory. */
	public Map<Source, Integer> where(int... itemIds)
	{
		final Map<Source, Integer> where = new EnumMap<>(Source.class);
		int pouch = 0;
		for (int id : itemIds)
		{
			pouch += runePouch.getOrDefault(id, 0);
		}
		items.forEach((source, counts) ->
		{
			int n = 0;
			for (int id : itemIds)
			{
				n += counts.getOrDefault(id, 0);
			}
			if (n > 0)
			{
				where.put(source, n);
			}
		});
		if (pouch > 0)
		{
			where.merge(Source.INVENTORY, pouch, Integer::sum);
		}
		return where;
	}

	/** Only what the player is carrying: inventory (with rune pouch) and worn items. */
	public Holdings carriedOnly()
	{
		final Map<Source, Map<Integer, Integer>> carried = new EnumMap<>(Source.class);
		carried.put(Source.INVENTORY, in(Source.INVENTORY));
		carried.put(Source.WORN, in(Source.WORN));
		return new Holdings(carried, runePouch, infiniteRunes, bankKnown, autoweedOn);
	}

	public Map<Integer, Integer> in(Source source)
	{
		return items.getOrDefault(source, Collections.emptyMap());
	}
}

package com.farmrunautopilot.supply;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.DataConstants;
import com.farmrunautopilot.data.SupplyItems;
import com.farmrunautopilot.data.travel.Rune;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.settings.SettingsStore;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.VarbitComposition;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * Keeps {@link Holdings} up to date (SPEC 11, 14). Inventory, equipment, rune pouch and leprechaun are
 * read live; the bank, group storage and seed vault are cached per account when their windows open,
 * because the game only sends them then. All methods except {@link #getHoldings()} run on the client
 * thread.
 */
@Slf4j
@Singleton
public class HoldingsTracker
{
	private static final String BANK_KEY = "cache.bank";
	private static final String GROUP_STORAGE_KEY = "cache.groupStorage";
	private static final String SEED_VAULT_KEY = "cache.seedVault";
	/** FARMING_BLOCKWEEDS value when Auto-weed is owned and switched on. */
	private static final int AUTOWEED_ON = 2;

	private static final int[] POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] POUCH_AMOUNT_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};

	/** Varbits whose changes affect holdings. */
	private static final Set<Integer> WATCHED_VARBITS = new HashSet<>();

	static
	{
		for (int varbit : POUCH_TYPE_VARBITS)
		{
			WATCHED_VARBITS.add(varbit);
		}
		for (int varbit : POUCH_AMOUNT_VARBITS)
		{
			WATCHED_VARBITS.add(varbit);
		}
		for (LeprechaunItem item : LeprechaunItem.values())
		{
			WATCHED_VARBITS.add(item.getBaseVarbit());
			if (item.getExtraVarbit() != DataConstants.NONE)
			{
				WATCHED_VARBITS.add(item.getExtraVarbit());
			}
		}
		WATCHED_VARBITS.add(VarbitID.FARMING_BLOCKWEEDS);
	}

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final ItemManager itemManager;
	private final SettingsStore settings;

	private Map<Integer, Integer> bank;
	private Map<Integer, Integer> groupStorage;
	private Map<Integer, Integer> seedVault;
	private boolean dirty = true;
	private volatile Holdings holdings = Holdings.EMPTY;

	@Inject
	HoldingsTracker(Client client, ConfigManager configManager, Gson gson, ItemManager itemManager,
		SettingsStore settings)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
		this.itemManager = itemManager;
		this.settings = settings;
	}

	public Holdings getHoldings()
	{
		return holdings;
	}

	/** Reload the cached containers for the current account (startup, account switch). */
	public void loadCaches()
	{
		bank = readCache(BANK_KEY);
		groupStorage = readCache(GROUP_STORAGE_KEY);
		seedVault = readCache(SEED_VAULT_KEY);
		dirty = true;
	}

	public void markDirty()
	{
		dirty = true;
	}

	public void onItemContainerChanged(int containerId, ItemContainer container)
	{
		switch (containerId)
		{
			case InventoryID.INV:
			case InventoryID.WORN:
				dirty = true;
				break;
			case InventoryID.BANK:
				bank = writeCache(BANK_KEY, container);
				dirty = true;
				break;
			case InventoryID.SEED_VAULT:
				seedVault = writeCache(SEED_VAULT_KEY, container);
				dirty = true;
				break;
			case InventoryID.INV_GROUP_TEMP:
				// Only save group storage once the player's edits are committed (as Quest Helper does).
				if (settings.getRunConfig().isUseGroupStorage()
					&& client.getVarbitValue(VarbitID.GIM_SHARED_BANK_HASEDITED) == 0)
				{
					groupStorage = writeCache(GROUP_STORAGE_KEY, container);
					dirty = true;
				}
				break;
			default:
				break;
		}
	}

	public void onVarbitChanged(int varbitId)
	{
		if (WATCHED_VARBITS.contains(varbitId))
		{
			dirty = true;
		}
	}

	/**
	 * Rebuilds the holdings if anything changed. Call once per game tick.
	 *
	 * @return whether the holdings changed
	 */
	public boolean rebuildIfDirty()
	{
		if (!dirty)
		{
			return false;
		}
		dirty = false;

		final RunConfig config = settings.getRunConfig();
		final Map<Holdings.Source, Map<Integer, Integer>> items = new EnumMap<>(Holdings.Source.class);
		final Map<Integer, Integer> inventory = read(client.getItemContainer(InventoryID.INV));
		final Map<Integer, Integer> worn = read(client.getItemContainer(InventoryID.WORN));
		items.put(Holdings.Source.INVENTORY, inventory);
		items.put(Holdings.Source.WORN, worn);
		if (bank != null)
		{
			items.put(Holdings.Source.BANK, bank);
		}
		items.put(Holdings.Source.LEPRECHAUN, readLeprechaun());
		if (config.isUseGroupStorage() && groupStorage != null)
		{
			items.put(Holdings.Source.GROUP_STORAGE, groupStorage);
		}
		if (config.isUseSeedVault() && seedVault != null)
		{
			items.put(Holdings.Source.SEED_VAULT, seedVault);
		}

		final Set<Rune> infinite = EnumSet.noneOf(Rune.class);
		for (Integer id : worn.keySet())
		{
			final Set<Rune> runes = SupplyItems.INFINITE_RUNE_ITEMS.get(id);
			if (runes != null)
			{
				infinite.addAll(runes);
			}
		}

		final Holdings next = new Holdings(Collections.unmodifiableMap(items), readRunePouch(inventory),
			Collections.unmodifiableSet(infinite), bank != null,
			client.getVarbitValue(VarbitID.FARMING_BLOCKWEEDS) == AUTOWEED_ON);
		if (next.equals(holdings))
		{
			return false;
		}
		holdings = next;
		return true;
	}

	private Map<Integer, Integer> read(ItemContainer container)
	{
		final Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				// Noted items and placeholders count as the real item.
				counts.merge(itemManager.canonicalize(item.getId()), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private Map<Integer, Integer> readRunePouch(Map<Integer, Integer> inventory)
	{
		boolean hasPouch = false;
		for (int pouch : SupplyItems.RUNE_POUCHES)
		{
			hasPouch |= inventory.containsKey(pouch);
		}
		if (!hasPouch)
		{
			return Collections.emptyMap();
		}

		final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		final Map<Integer, Integer> runes = new HashMap<>();
		for (int i = 0; i < POUCH_TYPE_VARBITS.length; i++)
		{
			final int type = client.getVarbitValue(POUCH_TYPE_VARBITS[i]);
			final int amount = client.getVarbitValue(POUCH_AMOUNT_VARBITS[i]);
			if (type != 0 && amount > 0)
			{
				runes.merge(runeEnum.getIntValue(type), amount, Integer::sum);
			}
		}
		return Collections.unmodifiableMap(runes);
	}

	private Map<Integer, Integer> readLeprechaun()
	{
		final Map<Integer, Integer> counts = new HashMap<>();
		for (LeprechaunItem item : LeprechaunItem.values())
		{
			if (item == LeprechaunItem.MAGIC_SECATEURS)
			{
				continue;
			}
			final int base = client.getVarbitValue(item.getBaseVarbit());
			final int extra = item.getExtraVarbit() == DataConstants.NONE ? 0 : client.getVarbitValue(item.getExtraVarbit());
			final int total = LeprechaunItem.combine(base, extra, bitsIn(item.getBaseVarbit()));
			if (total > 0)
			{
				counts.put(item.getItemId(), total);
			}
		}
		// The secateurs slot holds magic secateurs when this flag is set.
		if (client.getVarbitValue(LeprechaunItem.MAGIC_SECATEURS.getBaseVarbit()) > 0)
		{
			final Integer secateurs = counts.remove(LeprechaunItem.SECATEURS.getItemId());
			if (secateurs != null)
			{
				counts.put(LeprechaunItem.MAGIC_SECATEURS.getItemId(), secateurs);
			}
		}
		return counts;
	}

	private int bitsIn(int varbitId)
	{
		final VarbitComposition varbit = client.getVarbit(varbitId);
		return varbit == null ? 0 : varbit.getMostSignificantBit() - varbit.getLeastSignificantBit() + 1;
	}

	private Map<Integer, Integer> writeCache(String key, ItemContainer container)
	{
		final Map<Integer, Integer> counts = Collections.unmodifiableMap(read(container));
		final int[] pairs = new int[counts.size() * 2];
		int i = 0;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			pairs[i++] = e.getKey();
			pairs[i++] = e.getValue();
		}
		configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, gson.toJson(pairs));
		return counts;
	}

	private Map<Integer, Integer> readCache(String key)
	{
		final String json = configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
		if (json == null)
		{
			return null;
		}
		try
		{
			final int[] pairs = gson.fromJson(json, int[].class);
			final Map<Integer, Integer> counts = new HashMap<>();
			for (int i = 0; pairs != null && i + 1 < pairs.length; i += 2)
			{
				counts.put(pairs[i], pairs[i + 1]);
			}
			return Collections.unmodifiableMap(counts);
		}
		catch (JsonParseException e)
		{
			log.warn("Couldn't read cached {}", key, e);
			return null;
		}
	}
}

package com.farmrunautopilot.supply;

import static com.farmrunautopilot.data.DataConstants.NONE;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Items the tool leprechaun stores, read from player varbits (sent everywhere, so no need to visit).
 *
 * <p>Large counts are split over a base varbit and an "extra" varbit. The total is assumed to be
 * {@code base + (extra << bitsInBase)}: UNVERIFIED, confirm with the varbit inspector.
 */
@Getter
@RequiredArgsConstructor
public enum LeprechaunItem
{
	RAKE(ItemID.RAKE, VarbitID.FARMING_TOOLS_RAKE, VarbitID.FARMING_TOOLS_EXTRARAKES),
	SEED_DIBBER(ItemID.DIBBER, VarbitID.FARMING_TOOLS_DIBBER, VarbitID.FARMING_TOOLS_EXTRADIBBERS),
	SPADE(ItemID.SPADE, VarbitID.FARMING_TOOLS_SPADE, VarbitID.FARMING_TOOLS_EXTRASPADES),
	SECATEURS(ItemID.SECATEURS, VarbitID.FARMING_TOOLS_SECATEURS, VarbitID.FARMING_TOOLS_EXTRASECATEURS),
	/** A flag: the secateurs slot holds magic secateurs. */
	MAGIC_SECATEURS(ItemID.FAIRY_ENCHANTED_SECATEURS, VarbitID.FARMING_TOOLS_FAIRYSECATEURS, NONE),
	COMPOST(ItemID.BUCKET_COMPOST, VarbitID.FARMING_TOOLS_COMPOST, VarbitID.FARMING_TOOLS_EXTRACOMPOST),
	SUPERCOMPOST(ItemID.BUCKET_SUPERCOMPOST, VarbitID.FARMING_TOOLS_SUPERCOMPOST,
		VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST),
	ULTRACOMPOST(ItemID.BUCKET_ULTRACOMPOST, VarbitID.FARMING_TOOLS_ULTRACOMPOST, NONE),
	PLANT_CURE(ItemID.PLANT_CURE, VarbitID.FARMING_TOOLS_PLANTCURE, NONE);

	private final int itemId;
	private final int baseVarbit;
	/** Overflow varbit, or {@link com.farmrunautopilot.data.DataConstants#NONE}. */
	private final int extraVarbit;

	/**
	 * @param bitsInBase width of the base varbit
	 */
	public static int combine(int base, int extra, int bitsInBase)
	{
		return base + (extra << bitsInBase);
	}
}

