package com.farmrunautopilot.tracking;

import lombok.Value;

/**
 * Farming tick maths, following RuneLite core {@code FarmingTracker.getTickTime}. Crops grow on fixed
 * minute boundaries (every 5, 20, 40, 160 ... minutes), shifted by an account-specific offset that is
 * learned by watching a crop grow.
 */
@Value
public class FarmingTick
{
	/** Offset in minutes (stored as a positive number), or null if never observed. */
	Integer offsetMinutes;
	/** Tick rate the offset was observed on; longer rates give a more precise offset. */
	Integer offsetPrecisionMinutes;

	public static final FarmingTick UNKNOWN = new FarmingTick(null, null);

	/**
	 * Time (epoch seconds) of the tick boundary {@code ticks} ticks after the boundary at or before
	 * {@code epochSeconds}.
	 */
	public long tickTime(int tickMinutes, int ticks, long epochSeconds)
	{
		final long offsetSeconds = offsetSecondsFor(tickMinutes);
		final long shifted = epochSeconds + offsetSeconds;
		final long tickSeconds = tickMinutes * 60L;
		final long currentTick = shifted - (shifted % tickSeconds);
		return currentTick + ticks * tickSeconds - offsetSeconds;
	}

	private long offsetSecondsFor(int tickMinutes)
	{
		if (offsetMinutes == null || offsetPrecisionMinutes == null)
		{
			return 0;
		}
		if (offsetPrecisionMinutes >= tickMinutes || offsetPrecisionMinutes >= 40)
		{
			return (offsetMinutes % tickMinutes) * 60L;
		}
		return 0;
	}

	/**
	 * The offset implied by seeing a growth tick happen at {@code epochSeconds} on a crop with this tick
	 * rate.
	 */
	public static int observedOffsetMinutes(int tickMinutes, long epochSeconds)
	{
		return (int) Math.abs(((epochSeconds / 60) % tickMinutes) - tickMinutes);
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import lombok.Value;

/**
 * Best guess at a patch's state right now, worked forward from the last observation.
 */
@Value
public class PatchPrediction
{
	public enum Source
	{
		/** Seen by this plugin. */
		THIS_PLUGIN,
		/** Borrowed from RuneLite's Time Tracking plugin (patch not seen by us yet). */
		TIME_TRACKING
	}

	Patch patch;
	/** Null for empty or weedy patches and crops outside the v1 catalogue. */
	Crop crop;
	PatchState state;
	/** Growth stage, weed level or fruit count; see {@link com.farmrunautopilot.data.DecodedPatch}. */
	int stage;
	int stages;
	/**
	 * When growth (or weed regrowth, or fruit regrowth) finishes, in epoch seconds; 0 if nothing is
	 * changing on its own.
	 */
	long doneAt;
	long observedAt;
	/** When we saw this crop planted, in epoch seconds; 0 if unknown. */
	long plantedAt;
	Source source;
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.DecodedPatch;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchStateDecoder;
import com.farmrunautopilot.data.PatchType;

/**
 * Works a patch observation forward to "now" (SPEC 10.3), following RuneLite core
 * {@code FarmingTracker.predictPatch}.
 *
 * <p>Unlike RuneLite, weeds are not predicted to grow back on empty patches: in-game testing showed a raked
 * patch staying clear well past a 5 minute tick, so the last seen weed level is kept.
 */
public final class PatchPredictor
{
	/** A grown fruit tree holds 0-6 fruit. */
	static final int FRUIT_STAGES = 7;

	private PatchPredictor()
	{
	}

	public static PatchPrediction predict(Patch patch, PatchRecord record, long plantedAt,
		PatchPrediction.Source source, long now, FarmingTick tick, boolean leagues)
	{
		final DecodedPatch decoded = PatchStateDecoder.decode(patch.getType(), record.getValue());
		final Crop crop = decoded.getCrop();
		PatchState state = decoded.getState();
		int stage = decoded.getStage();
		int stages = 1;
		int tickMinutes = 0;

		if (state == PatchState.GROWING && crop != null)
		{
			tickMinutes = crop.getTickMinutes();
			stages = crop.getStages();
		}
		else if (state == PatchState.HARVESTABLE && patch.getType() == PatchType.FRUIT_TREE)
		{
			tickMinutes = Crop.FRUIT_REGROW_MINUTES;
			stages = FRUIT_STAGES;
		}

		if (leagues)
		{
			// Farming ticks on leagues worlds are 1 minute instead of 5
			tickMinutes /= 5;
		}

		long doneAt = 0;
		if (tickMinutes > 0)
		{
			final long tickNow = tick.tickTime(tickMinutes, 0, now);
			final long tickSeen = tick.tickTime(tickMinutes, 0, record.getObservedAt());
			final int ticksPassed = (int) ((tickNow - tickSeen) / (tickMinutes * 60L));

			doneAt = tick.tickTime(tickMinutes, stages - 1 - stage, tickSeen);
			stage = Math.min(stage + Math.max(ticksPassed, 0), stages - 1);

			if (state == PatchState.GROWING && stage == stages - 1)
			{
				state = patch.getType().isProtectable() ? PatchState.CHECK_HEALTH : PatchState.HARVESTABLE;
			}
		}

		return new PatchPrediction(patch, crop, state, stage, stages, doneAt, record.getObservedAt(), plantedAt, source);
	}

	/**
	 * Whether going from {@code previous} to {@code current} can only be the game's growth tick (not a
	 * player action), so its timing reveals the account's tick offset. Mirrors RuneLite core
	 * {@code FarmingTracker.isObservedGrowthTick}.
	 */
	public static boolean isObservedGrowthTick(PatchType type, DecodedPatch previous, DecodedPatch current)
	{
		final Crop crop = previous.getCrop();
		if (crop == null || current.getCrop() != crop)
		{
			return false;
		}

		switch (previous.getState())
		{
			case GROWING:
				switch (current.getState())
				{
					case GROWING:
					case CHECK_HEALTH:
						return current.getStage() - previous.getStage() == 1;
					case DISEASED:
						return true;
					case HARVESTABLE:
						// Trees only reach HARVESTABLE through the player's check-health.
						return !type.isProtectable();
					default:
						return false;
				}
			case DISEASED:
				return current.getState() == PatchState.DEAD;
			default:
				return false;
		}
	}

	/** Whether this change means the player just planted something. */
	public static boolean isPlanting(DecodedPatch previous, DecodedPatch current)
	{
		return current.getState() == PatchState.GROWING && current.getCrop() != null && current.getStage() == 0
			&& (previous.getCrop() == null || previous.getState() != PatchState.GROWING);
	}
}

package com.farmrunautopilot.tracking;

import lombok.Value;

/**
 * One saved observation of a patch: the raw varbit value and when it was seen. Stored as
 * {@code "<value>:<epochSeconds>"}, the same format as RuneLite core Time Tracking.
 */
@Value
public class PatchRecord
{
	int value;
	long observedAt;

	public String format()
	{
		return value + ":" + observedAt;
	}

	/**
	 * @return the record, or null if the text is missing or malformed
	 */
	public static PatchRecord parse(String text)
	{
		if (text == null)
		{
			return null;
		}
		final String[] parts = text.split(":");
		if (parts.length != 2)
		{
			return null;
		}
		try
		{
			final int value = Integer.parseInt(parts[0]);
			final long observedAt = Long.parseLong(parts[1]);
			return observedAt > 0 ? new PatchRecord(value, observedAt) : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.data.PatchType;

/**
 * Short plain-language descriptions of patch predictions for the sidebar.
 */
public final class PatchStatusText
{
	private PatchStatusText()
	{
	}

	/**
	 * e.g. "Ranarr - ready in 34m", "Magic - check health", "Empty".
	 */
	public static String describe(PatchPrediction p, long now)
	{
		if (p == null)
		{
			return "Not seen yet";
		}

		final String crop = p.getCrop() != null ? p.getCrop().getDisplayName() : null;
		final PatchType type = p.getPatch().getType();
		switch (p.getState())
		{
			case EMPTY:
				return "Empty";
			case WEEDS:
				return "Weeds";
			case GROWING:
				if (crop == null)
				{
					return "Something else growing";
				}
				return crop + " - ready in " + duration(p.getDoneAt() - now);
			case CHECK_HEALTH:
				return crop + " - check health";
			case HARVESTABLE:
				if (crop == null)
				{
					return "Something else ready";
				}
				if (type == PatchType.HERB)
				{
					return crop + " - ready to pick";
				}
				if (type == PatchType.FRUIT_TREE)
				{
					final int fruit = p.getStage();
					final String count = crop + " - " + fruit + " fruit";
					return fruit < p.getStages() - 1 && p.getDoneAt() > now
						? count + " (full in " + duration(p.getDoneAt() - now) + ")"
						: count;
				}
				return crop + " - grown, ready to clear";
			case STUMP:
				return crop + " - stump";
			case DISEASED:
				return (crop != null ? crop : "Crop") + " - diseased";
			case DEAD:
				return "Dead " + (crop != null ? crop : type.getDisplayName()).toLowerCase();
			default:
				return "Unknown state";
		}
	}

	/**
	 * e.g. "2h 05m", "45m", "<1m".
	 */
	public static String duration(long seconds)
	{
		if (seconds < 60)
		{
			return "<1m";
		}
		final long minutes = (seconds + 59) / 60;
		final long hours = minutes / 60;
		final long mins = minutes % 60;
		if (hours == 0)
		{
			return mins + "m";
		}
		return hours + "h " + (mins < 10 ? "0" : "") + mins + "m";
	}

	/**
	 * e.g. "seen 3h 10m ago".
	 */
	public static String age(long epochSeconds, long now)
	{
		final long seconds = now - epochSeconds;
		return seconds < 60 ? "seen just now" : "seen " + duration(seconds) + " ago";
	}
}

package com.farmrunautopilot.tracking;

import com.farmrunautopilot.FarmRunAutopilotConfig;
import com.farmrunautopilot.data.DecodedPatch;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchStateDecoder;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.config.ConfigManager;

/**
 * Records patch varbits while the player is near a patch and predicts every patch's state (SPEC 10).
 * Observations are stored per account under {@code patch.<regionId>.<varbitId>}.
 */
@Slf4j
@Singleton
public class PatchTracker
{
	private static final String PATCH_PREFIX = "patch.";
	private static final String PLANTED_SUFFIX = ".planted";
	private static final String AUTOWEED_KEY = "autoweed";
	private static final String TICK_OFFSET_KEY = "farmTickOffset";
	private static final String TICK_OFFSET_PRECISION_KEY = "farmTickOffsetPrecision";
	/** RuneLite core Time Tracking, read only as a fallback for patches we have never seen (SPEC 10.5). */
	private static final String TIME_TRACKING_GROUP = "timetracking";
	/** Re-save an unchanged observation at most this often, like core Time Tracking. */
	private static final long RESAVE_SECONDS = 5 * 60;

	private static final Map<Integer, List<Patch>> PATCHES_BY_REGION = new HashMap<>();

	static
	{
		for (Patch patch : Patch.values())
		{
			PATCHES_BY_REGION.computeIfAbsent(patch.getRegionId(), k -> new ArrayList<>()).add(patch);
			for (int region : patch.getExtraRegionIds())
			{
				PATCHES_BY_REGION.computeIfAbsent(region, k -> new ArrayList<>()).add(patch);
			}
		}
	}

	private final Client client;
	private final ConfigManager configManager;

	private Set<Patch> lastPatches = Collections.emptySet();
	/** When each patch was last seen unchanged this session; saved config only refreshes every few minutes.
	 * Written on the client thread, read on the Swing thread. */
	private final Map<Patch, Long> lastSeen = new ConcurrentHashMap<>();

	@Inject
	PatchTracker(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	/** Patches whose varbits the game is sending right now, i.e. the player is next to them. Client thread. */
	public Set<Patch> getPatchesInRange()
	{
		return lastPatches;
	}

	/** Forget per-session state, e.g. after logging in to another account. */
	public void reset()
	{
		lastPatches = Collections.emptySet();
		lastSeen.clear();
	}

	/**
	 * Saves the varbits of the patches around {@code location}. Call once per game tick on the client
	 * thread, with the player's location from the previous tick.
	 *
	 * @param ticksSinceModalClose game ticks since a modal interface was closed
	 * @return whether any saved data changed
	 */
	public boolean update(WorldPoint location, int ticksSinceModalClose)
	{
		// Varbits don't get sent when a modal widget is open
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getModalMode() != WidgetModalMode.NON_MODAL)
			{
				return false;
			}
		}

		boolean changed = false;

		// Saved for the supply calculator: no rake needed when Auto-weed is on (SPEC 11.4)
		final String autoweed = Integer.toString(client.getVarbitValue(VarbitID.FARMING_BLOCKWEEDS));
		if (!autoweed.equals(getConfig(AUTOWEED_KEY)))
		{
			setConfig(AUTOWEED_KEY, autoweed);
			changed = true;
		}

		final Set<Patch> patches = patchesAt(location);
		final boolean newRegionLoaded = !patches.equals(lastPatches);
		lastPatches = patches;

		final long now = Instant.now().getEpochSecond();
		for (Patch patch : patches)
		{
			final int value = client.getVarbitValue(patch.getVarbitId());
			final DecodedPatch current = PatchStateDecoder.decode(patch.getType(), value);
			if (current.getState() == PatchState.UNKNOWN)
			{
				continue;
			}

			lastSeen.put(patch, now);
			final PatchRecord stored = PatchRecord.parse(getConfig(key(patch)));
			if (stored != null && stored.getValue() == value)
			{
				// Unchanged: only refresh the timestamp every few minutes
				if (stored.getObservedAt() + RESAVE_SECONDS > now && now + 30 > stored.getObservedAt())
				{
					continue;
				}
			}
			else if (stored != null)
			{
				final DecodedPatch previous = PatchStateDecoder.decode(patch.getType(), stored.getValue());
				if (PatchPredictor.isPlanting(previous, current))
				{
					setConfig(key(patch) + PLANTED_SUFFIX, Long.toString(now));
					log.debug("Saw {} planted with {}", patch, current.getCrop());
				}
				// Right after arriving or closing an interface, a change may be old news, not a live tick
				if (!newRegionLoaded && ticksSinceModalClose > 1
					&& PatchPredictor.isObservedGrowthTick(patch.getType(), previous, current))
				{
					recordTickOffset(previous.getCrop().getTickMinutes(), now);
				}
			}

			setConfig(key(patch), new PatchRecord(value, now).format());
			changed = true;
		}
		return changed;
	}

	/**
	 * @return the predicted state of this patch now, or null if it has never been seen
	 */
	public PatchPrediction predict(Patch patch)
	{
		PatchPrediction.Source source = PatchPrediction.Source.THIS_PLUGIN;
		PatchRecord record = PatchRecord.parse(getConfig(key(patch)));
		if (record == null)
		{
			record = PatchRecord.parse(configManager.getRSProfileConfiguration(TIME_TRACKING_GROUP,
				patch.getRegionId() + "." + patch.getVarbitId()));
			source = PatchPrediction.Source.TIME_TRACKING;
		}
		if (record == null)
		{
			return null;
		}

		final Long seen = lastSeen.get(patch);
		if (seen != null && seen > record.getObservedAt() && source == PatchPrediction.Source.THIS_PLUGIN)
		{
			record = new PatchRecord(record.getValue(), seen);
		}
		return PatchPredictor.predict(patch, record, plantedAt(patch), source, Instant.now().getEpochSecond(),
			farmingTick(), isLeaguesWorld());
	}

	private void recordTickOffset(int tickMinutes, long now)
	{
		final int offset = FarmingTick.observedOffsetMinutes(tickMinutes, now);
		final Integer precision = parseInt(getConfig(TICK_OFFSET_PRECISION_KEY));
		log.debug("Observed a growth tick on a {} minute crop, offset {}", tickMinutes, offset);
		if (precision == null || tickMinutes >= precision)
		{
			setConfig(TICK_OFFSET_PRECISION_KEY, Integer.toString(tickMinutes));
			setConfig(TICK_OFFSET_KEY, Integer.toString(offset));
		}
	}

	private FarmingTick farmingTick()
	{
		return new FarmingTick(parseInt(getConfig(TICK_OFFSET_KEY)), parseInt(getConfig(TICK_OFFSET_PRECISION_KEY)));
	}

	private long plantedAt(Patch patch)
	{
		final String text = getConfig(key(patch) + PLANTED_SUFFIX);
		try
		{
			return text == null ? 0 : Long.parseLong(text);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static Set<Patch> patchesAt(WorldPoint location)
	{
		final List<Patch> candidates = PATCHES_BY_REGION.get(location.getRegionID());
		if (candidates == null)
		{
			return Collections.emptySet();
		}
		final Set<Patch> patches = EnumSet.noneOf(Patch.class);
		for (Patch patch : candidates)
		{
			if (patch.isInBounds(location))
			{
				patches.add(patch);
			}
		}
		return patches;
	}

	private boolean isLeaguesWorld()
	{
		final Set<WorldType> worldTypes = client.getWorldType();
		return worldTypes.contains(WorldType.SEASONAL) && !worldTypes.contains(WorldType.DEADMAN);
	}

	private static String key(Patch patch)
	{
		return PATCH_PREFIX + patch.getRegionId() + "." + patch.getVarbitId();
	}

	private String getConfig(String key)
	{
		return configManager.getRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key);
	}

	private void setConfig(String key, String value)
	{
		configManager.setRSProfileConfiguration(FarmRunAutopilotConfig.GROUP, key, value);
	}

	private static Integer parseInt(String text)
	{
		try
		{
			return text == null ? null : Integer.valueOf(text);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

