	public void regionAndVarbitPairsAreUnique()
	{
		final Set<String> seen = new HashSet<>();
		for (Patch patch : Patch.values())
		{
			assertTrue("duplicate region/varbit for " + patch, seen.add(patch.getRegionId() + "." + patch.getVarbitId()));
		}
