		{
			assertEquals(UNKNOWN, PatchStateDecoder.decode(type, -1).getState());
			assertEquals(UNKNOWN, PatchStateDecoder.decode(type, 256).getState());
		}
	}

	@Test
	public void unrecognisedValueHasNoCrop()
	{
		final DecodedPatch decoded = PatchStateDecoder.decode(PatchType.HERB, 220);
		assertEquals(UNKNOWN, decoded.getState());
		assertNull(decoded.getCrop());
	}

	/** Values 0-3: fully overgrown (0) down to raked clear (3). */
	private void weeds()
	{
		row(0, 0, null, WEEDS, 3, 3);
		row(1, 1, null, WEEDS, 2, 2);
		row(2, 2, null, WEEDS, 1, 1);
		row(3, 3, null, EMPTY, 0, 0);
	}

	private void fruit(Crop crop, int growLo, int growHi, int harvestLo, int harvestHi, int diseasedLo, int diseasedHi,
		int deadLo, int deadHi, int stump, int checkHealth)
	{
		row(growLo, growHi, crop, GROWING, 0, 5);
		row(harvestLo, harvestHi, crop, HARVESTABLE, 0, 6);
		row(diseasedLo, diseasedHi, crop, DISEASED, 1, 6);
		row(deadLo, deadHi, crop, DEAD, 1, 6);
		row(stump, stump, crop, STUMP, 0, 0);
		row(checkHealth, checkHealth, crop, CHECK_HEALTH, 6, 6);
	}

	/** Stage moves by one per value from stageAtLo to stageAtHi. */
	private void row(int lo, int hi, Crop crop, PatchState state, int stageAtLo, int stageAtHi)
	{
		final int step = Integer.signum(stageAtHi - stageAtLo);
		assertEquals("bad test row " + lo + "-" + hi, Math.abs(stageAtHi - stageAtLo), step == 0 ? 0 : hi - lo);
		for (int v = lo; v <= hi; v++)
		{
			final DecodedPatch previous = expected.put(v, new DecodedPatch(crop, state, stageAtLo + step * (v - lo)));
			assertNull("test rows overlap at " + v, previous);
		}
	}

	private void checkAll(PatchType type)
	{
		for (int v = 0; v <= 255; v++)
		{
			final DecodedPatch want = expected.getOrDefault(v, new DecodedPatch(null, UNKNOWN, 0));
			assertEquals(type + " value " + v, want, PatchStateDecoder.decode(type, v));
		}
	}
}

package com.farmrunautopilot.data.travel;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class TravelDataTest
{
	@Test
	public void everyLocationHasAPrimaryMethodForEachOfItsPatchTypes()
	{
		for (Location location : Location.values())
		{
			for (Patch patch : location.getPatches())
			{
				boolean found = false;
				for (TravelMethod method : TravelMethod.values())
				{
					found |= method.getDestination() == location && method.isPrimaryFor(patch.getType());
				}
				assertTrue("no primary method for " + patch, found);
			}
		}
	}

	@Test
	public void primaryOnlyForTypesTheDestinationHas()
	{
		for (TravelMethod method : TravelMethod.values())
		{
			final Set<PatchType> types = EnumSet.noneOf(PatchType.class);
			for (Patch patch : method.getDestination().getPatches())
			{
				types.add(patch.getType());
			}
			assertTrue(method.name(), types.containsAll(method.getPrimaryFor()));
		}
	}

	@Test
	public void methodsCarryWhatTheirKindNeeds()
	{
		for (TravelMethod method : TravelMethod.values())
		{
			final String name = method.name();
			assertNotNull(name, method.getWalk());
			switch (method.getKind())
			{
				case SPELL:
				case HOUSE_PORTAL:
					assertNotNull(name, method.getSpell());
					assertNull(name, method.getItem());
					break;
				case FAIRY_RING:
					assertNotNull(name, method.getFairyRingCode());
					assertTrue(name, method.getFairyRingCode().matches("[A-D][I-L][P-S]"));
					break;
				case SPIRIT_TREE:
					assertNull(name, method.getSpell());
					assertNull(name, method.getItem());
					break;
				default:
					assertNotNull(name, method.getItem());
					assertNull(name, method.getSpell());
			}
			if (method.getKind() != TravelKind.FAIRY_RING)
			{
				assertNull(name, method.getFairyRingCode());
			}
			if (method.getJewelleryBox() != null)
			{
				assertEquals(name, TravelKind.JEWELLERY, method.getKind());
			}
			if (method.getKind() == TravelKind.HOUSE_PORTAL)
			{
				assertEquals(name, Spell.TELEPORT_TO_HOUSE, method.getSpell());
			}
		}
	}

	@Test
	public void spellRunesArePositiveAndNotRepeated()
	{
		for (Spell spell : Spell.values())
		{
			final Set<Rune> seen = EnumSet.noneOf(Rune.class);
			for (RuneAmount amount : spell.getRunes())
			{
				assertTrue(spell.name(), amount.getQuantity() > 0);
				assertTrue(spell + " lists " + amount.getRune() + " twice", seen.add(amount.getRune()));
			}
			assertTrue(spell.name(), spell.getMagicLevel() >= 1 && spell.getMagicLevel() <= 99);
		}
		assertTrue(Spell.LUMBRIDGE_HOME_TELEPORT.getRunes().isEmpty());
		assertFalse(Spell.CATHERBY_TELEPORT.getRunes().isEmpty());
	}

	@Test
	public void tabletsAreUnique()
	{
		final Set<Integer> seen = new HashSet<>();
		for (Spell spell : Spell.values())
		{
			if (spell.hasTablet())
			{
				assertTrue("duplicate tablet for " + spell, seen.add(spell.getTabletItemId()));
			}
		}
	}

	@Test
	public void travelItemIdsAreUniqueAcrossItems()
	{
		final Set<Integer> seen = new HashSet<>();
		for (TravelItem item : TravelItem.values())
		{
			assertTrue(item.name(), item.getItemIds().length > 0);
			for (int id : item.getItemIds())
			{
				assertTrue(item + " repeats item " + id, seen.add(id));
			}
		}
	}

	@Test
	public void catherbyRuneCostMatchesSpec()
	{
		assertEquals(3, Spell.CATHERBY_TELEPORT.getRunes().size());
		assertEquals(RuneAmount.of(10, Rune.WATER), Spell.CATHERBY_TELEPORT.getRunes().get(0));
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.run.RunTimings;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class LearnedTimesTest
{
	private static LearnedTimes with(Double... seconds)
	{
		return new LearnedTimes(Collections.singletonMap(
			LearnedTimes.key("CATHERBY", "CAMELOT_TELEPORT", "DIRECT"), Arrays.asList(seconds)));
	}

	private static double adjust(LearnedTimes learned, double estimate)
	{
		return learned.adjust(Location.CATHERBY, TravelMethod.CAMELOT_TELEPORT, Departure.DIRECT, estimate);
	}

	@Test
	public void noSamplesKeepsTheEstimate()
	{
		assertEquals(30, adjust(LearnedTimes.NONE, 30), 1e-9);
	}

	@Test
	public void blendsUntilThreeSamples()
	{
		// One sample of 60s against a 30s estimate: one third of the way
		assertEquals(40, adjust(with(60.0), 30), 1e-9);
		// Three samples averaging 45s replace the estimate
		assertEquals(45, adjust(with(40.0, 45.0, 50.0), 30), 1e-9);
	}

	@Test
	public void ignoresOutliers()
	{
		// 200s is more than three times the 30s estimate (e.g. the player went to the bank)
		assertEquals(45, adjust(with(40.0, 45.0, 50.0, 200.0), 30), 1e-9);
	}

	@Test
	public void savedLegsBecomeSamplesExceptTheFirstLegAndWalks()
	{
		final LearnedTimes learned = RunTimings.learned(Arrays.asList(
			new RunTimings.Leg("CATHERBY", null, "START", 300, 1),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 2),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 3),
			new RunTimings.Leg("CATHERBY", "CAMELOT_TELEPORT", "DIRECT", 45, 4)));
		assertEquals(45, adjust(learned, 30), 1e-9);
	}

	@Test
	public void otherMethodsAreUnaffected()
	{
		final List<Double> samples = Arrays.asList(60.0, 60.0, 60.0);
		final LearnedTimes learned = new LearnedTimes(Collections.singletonMap(
			LearnedTimes.key("CATHERBY", "CAMELOT_TELEPORT", "POH_NEXUS"), samples));
		assertEquals(30, adjust(learned, 30), 1e-9);
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.MetaOrder;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.RouteMode;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.supply.Holdings;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Test;

public class RoutePlannerTest
{
	private static RoutePlanner.Leg leg(double seconds)
	{
		return new RoutePlanner.Leg(null, Departure.DIRECT, seconds, false);
	}

	/** Asymmetric costs where the cheap tour is 0 -> 2 -> 1 -> 3. */
	private static RoutePlanner.Leg[][] legs()
	{
		final double[][] c = {
			{0, 50, 1, 50},
			{50, 0, 50, 1},
			{50, 1, 0, 50},
			{1, 50, 50, 0},
		};
		final RoutePlanner.Leg[][] legs = new RoutePlanner.Leg[4][4];
		for (int i = 0; i < 4; i++)
		{
			for (int j = 0; j < 4; j++)
			{
				legs[i][j] = leg(c[i][j]);
			}
		}
		return legs;
	}

	private static RoutePlanner.Leg[] first(double... seconds)
	{
		return Arrays.stream(seconds).mapToObj(RoutePlannerTest::leg).toArray(RoutePlanner.Leg[]::new);
	}

	@Test
	public void exactOrderFindsTheCheapestTour()
	{
		final int[] order = RoutePlanner.exactOrder(first(1, 9, 9, 9), legs(), new double[4], -1);
		assertArrayEquals(new int[]{0, 2, 1, 3}, order);
	}

	@Test
	public void exactOrderRespectsTheStart()
	{
		final int[] order = RoutePlanner.exactOrder(first(1, 1, 1, 1), legs(), new double[4], 1);
		assertEquals(1, order[0]);
		assertArrayEquals(new int[]{1, 3, 0, 2}, order);
	}

	@Test
	public void nearestNeighbourMatchesExactOnASmallCase()
	{
		final int[] order = RoutePlanner.nearestNeighbourThenImprove(first(1, 9, 9, 9), legs(), new double[4], -1);
		assertArrayEquals(new int[]{0, 2, 1, 3}, order);
	}

	@Test
	public void endNearBankPullsTheBankLastWhenItCostsNothingElse()
	{
		final RoutePlanner.Leg[][] flat = new RoutePlanner.Leg[3][3];
		for (int i = 0; i < 3; i++)
		{
			for (int j = 0; j < 3; j++)
			{
				flat[i][j] = leg(5);
			}
		}
		final int[] order = RoutePlanner.exactOrder(first(5, 5, 5), flat, new double[]{30, 0, 30}, 0);
		assertEquals(1, order[2]);
	}

	@Test
	public void fixedOrderFollowsPreferenceThenAppendsTheRest()
	{
		final List<Location> stops = Arrays.asList(Location.CATHERBY, Location.WEISS, Location.LUMBRIDGE);
		final int[] order = RoutePlanner.fixedOrder(stops, Arrays.asList(Location.LUMBRIDGE, Location.CATHERBY), -1);
		assertArrayEquals(new int[]{2, 0, 1}, order);
	}

	@Test
	public void combinedMetaOrderHasEveryLocationOnce()
	{
		final List<Location> combined = MetaOrder.combined();
		final Set<Location> unique = EnumSet.noneOf(Location.class);
		unique.addAll(combined);
		assertEquals(combined.size(), unique.size());
		assertEquals(EnumSet.allOf(Location.class), unique);
		// Shared locations sit where they first appear: the Gnome Stronghold is in the tree order.
		assertTrue(combined.indexOf(Location.GNOME_STRONGHOLD) < combined.indexOf(Location.TREE_GNOME_VILLAGE));
	}

	@Test
	public void walksWhenNothingFasterIsUsableAndTakesTheSpiritTreeOnToTreeGnomeVillage()
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setStartLocation(Location.FALADOR_PARK);
		// No teleports owned and too low Magic to cast any: walking is the only way to the farm.
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.MAGIC, 1);
		levels.put(Skill.FARMING, 99);
		final AccessSnapshot noTeleports = new AccessSnapshot(true, Collections.emptyMap(), levels,
			Collections.emptySet(), Collections.emptySet(), null);
		final List<Patch> patches = Arrays.asList(Patch.FALADOR_TREE, Patch.FALADOR_HERB);
		final Route route = RoutePlanner.plan(patches, config, noTeleports, Holdings.EMPTY, new PohSetup());
		assertEquals(Location.FALADOR_PARK, route.getStops().get(0).getLocation());
		assertEquals(Departure.WALK, route.getStops().get(1).getDeparture());

		config.setStartLocation(Location.GNOME_STRONGHOLD);
		final Route gnomes = RoutePlanner.plan(
			Arrays.asList(Patch.GNOME_STRONGHOLD_FRUIT_TREE, Patch.TREE_GNOME_VILLAGE_FRUIT_TREE), config,
			AccessSnapshot.UNKNOWN, Holdings.EMPTY, new PohSetup());
		final RouteStop village = gnomes.getStops().get(1);
		assertEquals(Location.TREE_GNOME_VILLAGE, village.getLocation());
		assertEquals(TravelMethod.SPIRIT_TREE_TREE_GNOME_VILLAGE, village.getMethod());
	}

	@Test
	public void preferWalkingPairsFaladorParkAndTaverley()
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setStartLocation(Location.VARROCK);
		final List<Patch> patches = Arrays.asList(Patch.VARROCK_TREE, Patch.FALADOR_TREE, Patch.TAVERLEY_TREE);
		final Route walking = RoutePlanner.plan(patches, config, AccessSnapshot.UNKNOWN, Holdings.EMPTY, new PohSetup());
		// One teleport into the pair, then a walk between them
		assertEquals(Departure.WALK, walking.getStops().get(2).getDeparture());

		config.setPreferWalking(false);
		final Route fastest = RoutePlanner.plan(patches, config, AccessSnapshot.UNKNOWN, Holdings.EMPTY, new PohSetup());
		assertEquals(Departure.DIRECT, fastest.getStops().get(2).getDeparture());
	}

	@Test
	public void metaModeUsesTheWikiOrderAndStartsAtTheStart()
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setRouteMode(RouteMode.META);
		final List<Patch> patches = Arrays.asList(Patch.TAVERLEY_TREE, Patch.LUMBRIDGE_TREE, Patch.FARMING_GUILD_TREE);
		final Route route = RoutePlanner.plan(patches, config, AccessSnapshot.UNKNOWN, Holdings.EMPTY, new PohSetup());
		assertEquals(Location.FARMING_GUILD, route.getStops().get(0).getLocation());
		assertEquals(Location.LUMBRIDGE, route.getStops().get(1).getLocation());
		assertEquals(Location.TAVERLEY, route.getStops().get(2).getLocation());
	}

	@Test
	public void ownOrderFollowsTheSavedOrder()
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setRouteMode(RouteMode.OFF);
		config.setCustomOrder(Arrays.asList(Location.TAVERLEY, Location.LUMBRIDGE));
		final List<Patch> patches = Arrays.asList(Patch.TAVERLEY_TREE, Patch.LUMBRIDGE_TREE, Patch.FARMING_GUILD_TREE);
		final Route route = RoutePlanner.plan(patches, config, AccessSnapshot.UNKNOWN, Holdings.EMPTY, new PohSetup());
		assertEquals(Location.TAVERLEY, route.getStops().get(0).getLocation());
		assertEquals(Location.LUMBRIDGE, route.getStops().get(1).getLocation());
		assertEquals(Location.FARMING_GUILD, route.getStops().get(2).getLocation());
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.tracking.PatchPrediction;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.function.Function;
import org.junit.Test;

public class RunSelectorTest
{
	private static final long NOW = 1_700_000_000L;
	private static final long HOUR = 3600;

	private static PatchPrediction growing(Patch patch, long doneAt)
	{
		return new PatchPrediction(patch, null, PatchState.GROWING, 0, 7, doneAt, NOW, 0,
			PatchPrediction.Source.THIS_PLUGIN);
	}

	private static PatchPrediction ready(Patch patch)
	{
		return new PatchPrediction(patch, null, PatchState.HARVESTABLE, 0, 7, 0, NOW, 0,
			PatchPrediction.Source.THIS_PLUGIN);
	}

	private static RunConfig config(PatchType... types)
	{
		final RunConfig config = new RunConfig();
		config.setEnabledTypes(EnumSet.noneOf(PatchType.class));
		for (PatchType type : types)
		{
			config.getEnabledTypes().add(type);
		}
		return config.sanitise();
	}

	/** Fruit trees: one ready, the rest growing for another 2-8 hours. Herbs: all ready. */
	private static final Function<Patch, PatchPrediction> MIXED = p ->
	{
		if (p.getType() == PatchType.HERB || p == Patch.CATHERBY_FRUIT_TREE)
		{
			return ready(p);
		}
		return growing(p, NOW + (2 + p.ordinal() % 7) * HOUR);
	};

	private static RunSelection select(RunConfig config, Map<PatchType, TypeOverride> overrides)
	{
		return RunSelector.select(config, AccessSnapshot.UNKNOWN, MIXED, NOW, false, overrides);
	}

	@Test
	public void typesWithTooFewDuePatchesAreSkippedWithACountdown()
	{
		final RunSelection selection = select(config(PatchType.FRUIT_TREE, PatchType.HERB), Collections.emptyMap());
		assertTrue(selection.getIncludedTypes().contains(PatchType.HERB));
		assertFalse(selection.getIncludedTypes().contains(PatchType.FRUIT_TREE));
		assertEquals(10, selection.getPatches().size());

		// 100% of 7 fruit trees: ready when the slowest one is.
		final long readyAt = selection.getSkippedTypes().get(PatchType.FRUIT_TREE);
		long latest = 0;
		for (Patch patch : Patch.values())
		{
			if (patch.getType() == PatchType.FRUIT_TREE && patch != Patch.CATHERBY_FRUIT_TREE)
			{
				latest = Math.max(latest, MIXED.apply(patch).getDoneAt());
			}
		}
		assertEquals(latest, readyAt);
		assertEquals(1, (int) selection.getDueCounts().get(PatchType.FRUIT_TREE));
	}

	@Test
	public void lowerThresholdIncludesTheTypeAndListsWhatIsNotDue()
	{
		final RunConfig config = config(PatchType.FRUIT_TREE);
		config.setDueThresholdPercent(10);
		final RunSelection selection = select(config, Collections.emptyMap());
		assertTrue(selection.getIncludedTypes().contains(PatchType.FRUIT_TREE));
		assertEquals(1, selection.getPatches().size());
		assertEquals(6, selection.getNotDue().size());
	}

	@Test
	public void overridesWin()
	{
		final Map<PatchType, TypeOverride> overrides = new EnumMap<>(PatchType.class);
		overrides.put(PatchType.FRUIT_TREE, TypeOverride.INCLUDE);
		overrides.put(PatchType.HERB, TypeOverride.SKIP);
		final RunSelection selection = select(config(PatchType.FRUIT_TREE, PatchType.HERB), overrides);
		assertTrue(selection.getIncludedTypes().contains(PatchType.FRUIT_TREE));
		assertFalse(selection.getIncludedTypes().contains(PatchType.HERB));
		assertTrue(selection.getSkippedTypes().containsKey(PatchType.HERB));
		// Included anyway: only the due fruit tree is visited.
		assertEquals(1, selection.getPatches().size());
	}

	@Test
	public void untickedTypesAreIgnored()
	{
		final RunSelection selection = select(config(PatchType.HERB), Collections.emptyMap());
		assertFalse(selection.getSkippedTypes().containsKey(PatchType.TREE));
		assertFalse(selection.getIncludedTypes().contains(PatchType.TREE));
	}

	@Test
	public void neededDueRoundsUp()
	{
		assertEquals(7, RunSelector.neededDue(7, 100));
		assertEquals(4, RunSelector.neededDue(7, 50));
		assertEquals(1, RunSelector.neededDue(7, 1));
	}
}

package com.farmrunautopilot.route;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.access.AccessSnapshot;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.poh.PohAltar;
import com.farmrunautopilot.data.travel.Spell;
import com.farmrunautopilot.data.travel.Spellbook;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.farmrunautopilot.settings.PohSetup;
import com.farmrunautopilot.settings.RunConfig;
import com.farmrunautopilot.supply.Holdings;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;

/** Sean asked not to be sent across spellbooks unless a house altar makes it practical. */
public class SpellbookRuleTest
{
	private static AccessSnapshot onBook(Spellbook book, Set<Spellbook> altar)
	{
		final Map<Quest, QuestState> quests = new EnumMap<>(Quest.class);
		quests.put(Quest.PRIEST_IN_PERIL, QuestState.FINISHED);
		final Map<Skill, Integer> levels = new EnumMap<>(Skill.class);
		levels.put(Skill.MAGIC, 99);
		levels.put(Skill.FARMING, 99);
		return new AccessSnapshot(true, quests, levels, Collections.emptySet(), Collections.emptySet(), null, book,
			altar);
	}

	private static RouteStop portPhasmatys(AccessSnapshot access)
	{
		final RunConfig config = new RunConfig().sanitise();
		config.setStartLocation(Location.PORT_PHASMATYS);
		return RoutePlanner.plan(Collections.singletonList(Patch.PORT_PHASMATYS_HERB), config, access, Holdings.EMPTY,
			new PohSetup()).getStops().get(0);
	}

	@Test
	public void spellsFromAnotherBookNeedAnAltar()
	{
		final AccessSnapshot standard = onBook(Spellbook.STANDARD, Collections.emptySet());
		assertTrue(standard.canCast(Spell.CAMELOT_TELEPORT));
		assertFalse(standard.canCast(Spell.FENKENSTRAINS_CASTLE_TELEPORT));

		final AccessSnapshot withAltar = onBook(Spellbook.STANDARD, PohAltar.DARK.getSpellbooks());
		assertTrue(withAltar.canCast(Spell.FENKENSTRAINS_CASTLE_TELEPORT));
		assertFalse(withAltar.isOnSpellbook(Spell.FENKENSTRAINS_CASTLE_TELEPORT));
	}

	@Test
	public void routeOnlyCastsFromTheCurrentBook()
	{
		// On the standard book with no altar: it can't be cast, so it's only planned as a tablet to bring.
		final RouteStop standard = portPhasmatys(onBook(Spellbook.STANDARD, Collections.emptySet()));
		assertTrue(standard.getMethod() != TravelMethod.FENKENSTRAINS_CASTLE_TELEPORT || standard.isNeedsSupplies());
		// On Arceuus it's cast from runes.
		final RouteStop arceuus = portPhasmatys(onBook(Spellbook.ARCEUUS, Collections.emptySet()));
		assertEquals(TravelMethod.FENKENSTRAINS_CASTLE_TELEPORT, arceuus.getMethod());
		assertFalse(arceuus.isNeedsSupplies());
	}
}

