package com.farmrunautopilot.run;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchState;
import com.farmrunautopilot.settings.Compost;
import com.farmrunautopilot.tracking.PatchPrediction;
import org.junit.Test;

public class StepAdvisorTest
{
	private static PatchPrediction live(Patch patch, Crop crop, PatchState state, int stage)
	{
		return new PatchPrediction(patch, crop, state, stage, 7, 0, 0, 0, PatchPrediction.Source.THIS_PLUGIN);
	}

	private static StepAdvisor.PatchGoal herb(boolean composted)
	{
		return new StepAdvisor.PatchGoal(Patch.CATHERBY_HERB, Crop.RANARR, "Ranarr seed", Compost.ULTRACOMPOST,
			false, null, false, composted, false, true);
	}

	private static StepAdvisor.PatchGoal tree(boolean payToClear, boolean paid)
	{
		return new StepAdvisor.PatchGoal(Patch.TAVERLEY_TREE, Crop.MAGIC, "Magic sapling", Compost.NONE,
			true, "25 x Coconut (noted is fine)", payToClear, false, paid, true);
	}

	private static StepAdvisor.Action action(StepAdvisor.PatchGoal goal, PatchPrediction live)
	{
		return StepAdvisor.advise(goal, live).getAction();
	}

	@Test
	public void herbRunSequence()
	{
		final Patch p = Patch.CATHERBY_HERB;
		assertEquals(StepAdvisor.Action.INSPECT, action(herb(false), null));
		assertEquals(StepAdvisor.Action.PICK, action(herb(false), live(p, Crop.RANARR, PatchState.HARVESTABLE, 2)));
		assertEquals(StepAdvisor.Action.RAKE, action(herb(false), live(p, null, PatchState.WEEDS, 2)));
		assertEquals(StepAdvisor.Action.COMPOST, action(herb(false), live(p, null, PatchState.EMPTY, 0)));
		assertEquals("Plant: Ranarr seed", StepAdvisor.advise(herb(true), live(p, null, PatchState.EMPTY, 0)).getText());
		assertEquals(StepAdvisor.Action.DONE, action(herb(true), live(p, Crop.RANARR, PatchState.GROWING, 0)));
		assertEquals(StepAdvisor.Action.CLEAR_DEAD, action(herb(false), live(p, null, PatchState.DEAD, 1)));
	}

	@Test
	public void treeRunSequence()
	{
		final Patch p = Patch.TAVERLEY_TREE;
		assertEquals(StepAdvisor.Action.CHECK_HEALTH,
			action(tree(true, false), live(p, Crop.MAGIC, PatchState.CHECK_HEALTH, 12)));
		assertEquals("Ask Alain to remove the tree (200 coins)",
			StepAdvisor.advise(tree(true, false), live(p, Crop.MAGIC, PatchState.HARVESTABLE, 0)).getText());
		assertEquals(StepAdvisor.Action.CHOP, action(tree(false, false), live(p, Crop.MAGIC, PatchState.HARVESTABLE, 0)));
		assertEquals(StepAdvisor.Action.DIG_STUMP, action(tree(false, false), live(p, Crop.MAGIC, PatchState.STUMP, 0)));
		assertEquals("Pay Alain: 25 x Coconut (noted is fine)",
			StepAdvisor.advise(tree(true, false), live(p, Crop.MAGIC, PatchState.GROWING, 0)).getText());
		assertEquals(StepAdvisor.Action.DONE, action(tree(true, true), live(p, Crop.MAGIC, PatchState.GROWING, 0)));
	}

	@Test
	public void fruitIsPickedBeforeClearing()
	{
		final Patch p = Patch.CATHERBY_FRUIT_TREE;
		final StepAdvisor.PatchGoal goal = new StepAdvisor.PatchGoal(p, Crop.PALM, "Palm sapling", Compost.NONE, true,
			"15 x Papaya fruit", true, false, false, true);
		assertEquals(StepAdvisor.Action.PICK, action(goal, live(p, Crop.PALM, PatchState.HARVESTABLE, 6)));
		assertEquals(StepAdvisor.Action.PAY_TO_CLEAR, action(goal, live(p, Crop.PALM, PatchState.HARVESTABLE, 0)));
	}

	@Test
	public void objectivesAreShort()
	{
		assertEquals("Herb: harvest guam and plant ranarr", StepAdvisor.objectives(Patch.CATHERBY_HERB,
			live(Patch.CATHERBY_HERB, Crop.GUAM, PatchState.HARVESTABLE, 4), Crop.RANARR));
		assertEquals("Fruit tree: pick papaya, clear and plant papaya", StepAdvisor.objectives(
			Patch.CATHERBY_FRUIT_TREE, live(Patch.CATHERBY_FRUIT_TREE, Crop.PAPAYA, PatchState.HARVESTABLE, 6),
			Crop.PAPAYA));
		assertEquals("Tree: check health of yew, clear and plant magic", StepAdvisor.objectives(Patch.TAVERLEY_TREE,
			live(Patch.TAVERLEY_TREE, Crop.YEW, PatchState.CHECK_HEALTH, 0), Crop.MAGIC));
		assertEquals("Herb: check the patch and plant ranarr",
			StepAdvisor.objectives(Patch.CATHERBY_HERB, null, Crop.RANARR));
	}

	@Test
	public void checkHealthNamesTheTree()
	{
		assertEquals("Check the health of the yew tree (replanting: Magic sapling)",
			StepAdvisor.advise(tree(false, false), live(Patch.TAVERLEY_TREE, Crop.YEW, PatchState.CHECK_HEALTH, 0))
				.getText());
	}
@Test
	public void noPaymentForATreeThatWasAlreadyGrowing()
	{
		final StepAdvisor.PatchGoal alreadyGrowing = new StepAdvisor.PatchGoal(Patch.TAVERLEY_TREE, Crop.MAGIC,
			"Magic sapling", Compost.NONE, true, "25 x Coconut", false, false, false, false);
		assertEquals(StepAdvisor.Action.DONE,
			action(alreadyGrowing, live(Patch.TAVERLEY_TREE, Crop.MAGIC, PatchState.GROWING, 3)));
		assertEquals(StepAdvisor.Action.PAY,
			action(tree(false, false), live(Patch.TAVERLEY_TREE, Crop.MAGIC, PatchState.GROWING, 0)));
	}
}

package com.farmrunautopilot.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Location;
import com.farmrunautopilot.data.Patch;
import com.farmrunautopilot.data.PatchType;
import com.farmrunautopilot.data.Unlock;
import com.farmrunautopilot.data.poh.HousePortal;
import com.farmrunautopilot.data.poh.PortalNexus;
import com.farmrunautopilot.data.travel.TravelMethod;
import com.google.gson.Gson;
import org.junit.Test;

public class RunConfigTest
{
	// The plugin uses RuneLite's injected Gson; a plain one behaves the same for these classes.
	private final Gson gson = new Gson();

	@Test
	public void presetCopiesMatchTheSettingsTheyWereSavedFrom()
	{
		// SettingsStore.activePreset() relies on a saved copy comparing equal to the live settings
		final RunConfig config = new RunConfig().sanitise();
		config.getEnabledTypes().remove(PatchType.TREE);
		config.getCrops().put(PatchType.HERB, Crop.TORSTOL);
		config.setOutfit(Outfit.GRACEFUL);
		final Preset preset = new Preset("Quick herbs", gson.fromJson(gson.toJson(config), RunConfig.class).sanitise());
		final Preset[] saved = gson.fromJson(gson.toJson(new Preset[]{preset}), Preset[].class);
		assertEquals(config, saved[0].getConfig().sanitise());

		config.setStaminaDoses(4);
		assertFalse(config.equals(saved[0].getConfig()));
	}

	@Test
	public void defaults()
	{
		final RunConfig config = new RunConfig().sanitise();
		assertEquals(3, config.getEnabledTypes().size());
		assertTrue(config.isPayWithNotes());
		assertFalse(config.isUseGroupStorage());
		assertFalse(config.isUseSeedVault());
		assertEquals(Location.FARMING_GUILD, config.getStartLocation());
		assertEquals(Protection.PAY_GARDENER, config.protectionFor(Patch.TAVERLEY_TREE));
		assertEquals(Compost.ULTRACOMPOST, config.getCompost().get(PatchType.HERB));
	}

	@Test
	public void roundTripThroughJson()
	{
		final RunConfig config = new RunConfig();
		config.getDisabledPatches().add(Patch.LUMBRIDGE_TREE);
		config.getCrops().put(PatchType.HERB, Crop.RANARR);
		config.getProtectionOverrides().put(Patch.FALADOR_TREE, Protection.COMPOST_ONLY);
		config.getTravel().put(Location.CATHERBY, TravelMethod.CATHERBY_TELEPORT);
		config.setRouteMode(RouteMode.META);
		config.setStaminaDoses(4);

		final RunConfig loaded = gson.fromJson(gson.toJson(config), RunConfig.class).sanitise();
		assertEquals(config, loaded);
		assertFalse(loaded.isPatchSelected(Patch.LUMBRIDGE_TREE));
		assertEquals(Protection.COMPOST_ONLY, loaded.protectionFor(Patch.FALADOR_TREE));
	}

	@Test
	public void sanitiseRepairsBadSaves()
	{
		// Unknown enum names, wrong crop for a type, a method for another location, nulls, a setting that no longer
		// exists (energyThreshold).
		final String json = "{\"enabledTypes\":[\"TREE\",\"NOT_A_TYPE\"],"
			+ "\"crops\":{\"HERB\":\"MAGIC\",\"TREE\":\"YEW\"},"
			+ "\"travel\":{\"CATHERBY\":\"FARMING_CAPE\",\"LLETYA\":\"TELEPORT_CRYSTAL_LLETYA\"},"
			+ "\"protection\":null,\"routeMode\":\"GONE\",\"energyThreshold\":500,\"customOrder\":null}";
		final RunConfig config = gson.fromJson(json, RunConfig.class).sanitise();

		assertEquals(1, config.getEnabledTypes().size());
		assertEquals(Crop.YEW, config.getCrops().get(PatchType.TREE));
		assertFalse(config.getCrops().containsKey(PatchType.HERB));
		assertFalse(config.getTravel().containsKey(Location.CATHERBY));
		assertEquals(TravelMethod.TELEPORT_CRYSTAL_LLETYA, config.getTravel().get(Location.LLETYA));
		assertEquals(Protection.PAY_GARDENER, config.getProtection().get(PatchType.TREE));
		assertEquals(RouteMode.AUTOPILOT, config.getRouteMode());
		assertNotNull(config.getCustomOrder());
	}

	@Test
	public void cropDefaultsToHighestPlantable()
	{
		final RunConfig config = new RunConfig();
		assertEquals(Crop.MAGIC, config.cropFor(PatchType.TREE, 99));
		assertEquals(Crop.MAPLE, config.cropFor(PatchType.TREE, 59));
		assertEquals(Crop.OAK, config.cropFor(PatchType.TREE, 1));
		assertEquals(Crop.HUASCA, config.cropFor(PatchType.HERB, 66));
		config.getCrops().put(PatchType.TREE, Crop.WILLOW);
		assertEquals(Crop.WILLOW, config.cropFor(PatchType.TREE, 99));
	}

	@Test
	public void backupCropChoices()
	{
		final String json = "{\"crops\":{\"HERB\":\"RANARR\"},\"useBackupCrops\":true,"
			+ "\"backupCrops\":{\"HERB\":[\"RANARR\",\"TORSTOL\",\"TOADFLAX\",\"MAGIC\",\"GUAM\"]}}";
		final RunConfig config = gson.fromJson(json, RunConfig.class).sanitise();
		// Duplicates of the same crop and other run types' crops are dropped; at most two backups are kept.
		assertEquals(java.util.Arrays.asList(Crop.RANARR, Crop.TORSTOL), config.getBackupCrops().get(PatchType.HERB));
		// Torstol needs 85 Farming, so at 50 it is skipped.
		assertEquals(java.util.Arrays.asList(Crop.RANARR), config.cropChoices(PatchType.HERB, 50));
		assertEquals(java.util.Arrays.asList(Crop.RANARR, Crop.TORSTOL), config.cropChoices(PatchType.HERB, 99));

		config.setUseBackupCrops(false);
		assertEquals(java.util.Arrays.asList(Crop.RANARR), config.cropChoices(PatchType.HERB, 99));
	}

	@Test
	public void runesNotTabs()
	{
		final RunConfig config = new RunConfig();
		assertFalse(config.useRunesAt(Location.CATHERBY));
		config.getRunesNotTabsAt().add(Location.CATHERBY);
		assertTrue(config.useRunesAt(Location.CATHERBY));
		assertFalse(config.useRunesAt(Location.LUMBRIDGE));
		config.setUseRunesNotTabs(true);
		assertTrue(config.useRunesAt(Location.LUMBRIDGE));
	}

	@Test
	public void accountSettingsRoundTrip()
	{
		final AccountSettings account = new AccountSettings();
		account.getManualUnlocks().add(Unlock.FIRE_OF_NOURISHMENT);
		account.getPoh().setPortal(HousePortal.TAVERLEY);
		account.getPoh().getNexusDestinations().add(PortalNexus.Destination.WEISS);

		final AccountSettings loaded = gson.fromJson(gson.toJson(account), AccountSettings.class).sanitise();
		assertEquals(account, loaded);

		final AccountSettings repaired = gson.fromJson("{\"poh\":null,\"manualUnlocks\":null}", AccountSettings.class)
			.sanitise();
		assertNotNull(repaired.getPoh());
		assertTrue(repaired.getManualUnlocks().isEmpty());
	}
}

package com.farmrunautopilot.supply;

import static org.junit.Assert.assertEquals;
import com.farmrunautopilot.data.Crop;
import com.farmrunautopilot.data.Patch;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import org.junit.Test;

public class CropAllocatorTest
{
	private static final List<Patch> HERBS = Arrays.asList(Patch.FALADOR_HERB, Patch.CATHERBY_HERB, Patch.ARDOUGNE_HERB,
		Patch.TROLL_STRONGHOLD_HERB, Patch.WEISS_HERB, Patch.HARMONY_ISLAND_HERB);
	private static final Set<Patch> DISEASE_FREE = EnumSet.of(Patch.TROLL_STRONGHOLD_HERB, Patch.WEISS_HERB,
		Patch.HARMONY_ISLAND_HERB);
	private static final Predicate<Patch> SAFE = DISEASE_FREE::contains;
	private static final List<Crop> TOADFLAX_THEN_GUAM = Arrays.asList(Crop.TOADFLAX, Crop.GUAM);
	private static final List<Crop> NONE_RESERVED = Collections.emptyList();

	private static Map<Crop, Integer> stock(Object... cropThenCount)
	{
		final Map<Crop, Integer> stock = new HashMap<>();
		for (int i = 0; i < cropThenCount.length; i += 2)
		{
			stock.put((Crop) cropThenCount[i], (Integer) cropThenCount[i + 1]);
		}
		return stock;
	}

	private static Map<Patch, Crop> allocate(List<Crop> choices, Map<Crop, Integer> stock, List<Crop> reserved)
	{
		return CropAllocator.allocate(HERBS, choices, c -> stock.getOrDefault(c, 0), SAFE, reserved);
	}

	private static int count(Map<Patch, Crop> plan, Crop crop)
	{
		return Collections.frequency(plan.values(), crop);
	}

	@Test
	public void singleChoiceFillsEveryPatch()
	{
		final Map<Patch, Crop> plan = allocate(Collections.singletonList(Crop.RANARR), stock(Crop.RANARR, 1), NONE_RESERVED);
		assertEquals(6, count(plan, Crop.RANARR));
	}

	@Test
	public void shortStockFallsBackInOrderAndSafePatchesGetTheBest()
	{
		final List<Crop> choices = Arrays.asList(Crop.RANARR, Crop.TOADFLAX, Crop.GUAM);
		final Map<Patch, Crop> plan = allocate(choices, stock(Crop.RANARR, 3, Crop.TOADFLAX, 2, Crop.GUAM, 10),
			NONE_RESERVED);
		// Three ranarr go to the three disease-free patches.
		for (Patch patch : DISEASE_FREE)
		{
			assertEquals(Crop.RANARR, plan.get(patch));
		}
		assertEquals(2, count(plan, Crop.TOADFLAX));
		assertEquals(1, count(plan, Crop.GUAM));
	}

	@Test
	public void whenEverythingRunsOutTheFirstChoiceIsShort()
	{
		final List<Crop> choices = Arrays.asList(Crop.RANARR, Crop.TOADFLAX, Crop.GUAM);
		final Map<Patch, Crop> plan = allocate(choices, stock(Crop.RANARR, 1, Crop.TOADFLAX, 1, Crop.GUAM, 1),
			NONE_RESERVED);
		assertEquals(1, count(plan, Crop.TOADFLAX));
		assertEquals(1, count(plan, Crop.GUAM));
		assertEquals(4, count(plan, Crop.RANARR));
	}

	@Test
	public void reservedHerbsGoOnlyToDiseaseFreePatchesBestFirst()
	{
		// Snapdragon ranked above ranarr. Plenty of both, but other patches never get them.
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM,
			stock(Crop.SNAPDRAGON, 2, Crop.RANARR, 10, Crop.TOADFLAX, 10),
			Arrays.asList(Crop.SNAPDRAGON, Crop.RANARR));
		assertEquals(2, count(plan, Crop.SNAPDRAGON));
		assertEquals(1, count(plan, Crop.RANARR));
		assertEquals(3, count(plan, Crop.TOADFLAX));
		assertEquals(Crop.TOADFLAX, plan.get(Patch.CATHERBY_HERB));
	}

	@Test
	public void diseaseFreePatchesFallBackToNormalChoicesWhenReservedRunOut()
	{
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM, stock(Crop.RANARR, 1, Crop.TOADFLAX, 10),
			Collections.singletonList(Crop.RANARR));
		assertEquals(1, count(plan, Crop.RANARR));
		assertEquals(5, count(plan, Crop.TOADFLAX));
	}

	@Test
	public void reservedFirstChoiceIsKeptOutOfRiskyPatches()
	{
		// Ranarr is both the 1st choice and reserved: risky patches get the 2nd choice.
		final Map<Patch, Crop> plan = allocate(Arrays.asList(Crop.RANARR, Crop.TOADFLAX),
			stock(Crop.RANARR, 10, Crop.TOADFLAX, 10), Collections.singletonList(Crop.RANARR));
		assertEquals(3, count(plan, Crop.RANARR));
		assertEquals(Crop.TOADFLAX, plan.get(Patch.FALADOR_HERB));
	}

	@Test
	public void resultKeepsThePatchOrder()
	{
		final Map<Patch, Crop> plan = allocate(TOADFLAX_THEN_GUAM, stock(Crop.TOADFLAX, 5), NONE_RESERVED);
		assertEquals(HERBS, Arrays.asList(plan.keySet().toArray(new Patch[0])));
	}
}

package com.farmrunautopilot.supply;

import static org.junit.Assert.assertEquals;
